// p without '.' or '..' parts, or null when it climbs out of the repository
function jsNormalize(p) {
  const out = [];
  for (const part of p.split('/')) {
    if (part === '..') { if (!out.length) return null; out.pop(); }
    else if (part && part !== '.') out.push(part);
  }
  return out.join('/');
}

function jsHas(files, p) {
  let lo = 0, hi = files.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (files[mid] === p) return true;
    if (files[mid] < p) lo = mid + 1; else hi = mid - 1;
  }
  return false;
}

// a relative or root-relative spec to the repo file it names; a package (a bare spec) is not in the repo
function jsResolve(spec, fromPath, files) {
  if (typeof spec !== 'string' || !(spec.startsWith('.') || spec.startsWith('/'))) return null;
  const dir = fromPath.includes('/') ? fromPath.slice(0, fromPath.lastIndexOf('/')) : '';
  const clean = spec.replace(/[?#].*$/, '');
  const base = jsNormalize(clean.startsWith('/') ? clean : `${dir}/${clean}`);
  if (base === null) return null;
  const ext = /\.[^./]+$/.exec(base), tries = [];
  if (base) tries.push(base, ...JS_PROBE.map((e) => base + e));
  if (ext && JS_SWAP[ext[0]]) tries.splice(1, 0, ...JS_SWAP[ext[0]].map((e) => base.slice(0, -ext[0].length) + e));
  tries.push(...JS_PROBE.map((e) => `${base ? `${base}/` : ''}index${e}`));
  return tries.find((p) => jsHas(files, p)) || null;
}

const jsLang = {
  id: 'js',
  exts: JS_EXTS,
  // a name reaches another file only through an import, so a call is never matched to another file by name alone
  moduleScope: true,
  extract: jsExtract,
  resolve: jsResolve,
};

// ---- server/codemap/lang/kotlin.js ----
// Kotlin: comments (block comments nest) and string contents are blanked first, keeping line numbers. Declarations are
// read at paren depth 0 and at the member depth that braces give, so a parameter list or a body never reads as members.

const ktCallSkip = new Set(['if', 'when', 'while', 'for', 'catch', 'return', 'throw', 'super', 'this']);
const ktTypeRe = /^(\s*(?:@[\w.]+(?:\([^)]*\))?\s+)*)((?:(?:public|private|protected|internal|open|abstract|final|sealed|data|inner|annotation|value|enum|companion|const|fun|override)\s+)*)(class|interface|object)\b(?:\s+([A-Za-z_]\w*))?/;
const ktFunRe = /^(\s*(?:@[\w.]+(?:\([^)]*\))?\s+)*)((?:(?:public|private|protected|internal|open|override|abstract|final|suspend|inline|infix|operator|tailrec|external|actual|expect)\s+)*)fun\s+(?:<[^>]*>\s*)?(?:([\w$.<>?, ]+?)\.)?([A-Za-z_]\w*)\s*\(/;
const ktValRe = /^(\s*(?:@[\w.]+(?:\([^)]*\))?\s+)*)((?:(?:public|private|protected|internal|const|lateinit|override|open|final)\s+)*)(val|var)\s+([A-Za-z_]\w*)(?=\s*(?:[:=]|$|by\b))/;
const ktImportRe = /^\s*import\s+([\w$.]+(?:\.\*)?)(?:\s+as\s+[\w$]+)?\s*;?\s*$/;
// Explicit type arguments (mutableListOf<Line>()) are part of the call.
const ktCallRe = /(?<![@\w$])([A-Za-z_$][\w$]*)\s*(?:<[^()<>]*>\s*)?\(/g;
const ktAnnotationRe = /@((?:[A-Za-z_]\w*\.)*[A-Za-z_]\w*)(?!\s*:)/g;
const ktIndexes = new WeakMap();

function ktStrip(text) {
  const out = [];
  const n = text.length;
  const blankKeepLines = (s) => s.replace(/[^\n]/g, ' ');
  let i = 0;
  while (i < n) {
    const c = text[i];
    if (c === '/' && text[i + 1] === '/') {
      const end = text.indexOf('\n', i);
      const stop = end === -1 ? n : end;
      out.push(blankKeepLines(text.slice(i, stop)));
      i = stop;
    } else if (c === '/' && text[i + 1] === '*') {
      // Kotlin block comments nest: a '/*' inside a comment opens another level.
      let level = 1;
      let j = i + 2;
      while (j < n && level > 0) {
        if (text[j] === '/' && text[j + 1] === '*') {
          level += 1;
          j += 2;
        } else if (text[j] === '*' && text[j + 1] === '/') {
          level -= 1;
          j += 2;
        } else {
          j += 1;
        }
      }
      out.push(blankKeepLines(text.slice(i, j)));
      i = j;
    } else if (text.startsWith('"""', i)) {
      // A raw string has no escapes, so it ends at the next triple quote.
      const close = text.indexOf('"""', i + 3);
      const stop = close === -1 ? n : close + 3;
      out.push(`""${text.slice(i, stop).replace(/[^\n]/g, '')}`);
      i = stop;
    } else if (c === '"' || c === "'") {
      // A string or char literal ends at its quote or at the line end, so a bad literal cannot hide later lines.
      let j = i + 1;
      while (j < n && text[j] !== c && text[j] !== '\n') j += text[j] === '\\' && text[j + 1] !== '\n' ? 2 : 1;
      out.push(c + c);
      i = j < n && text[j] === c ? j + 1 : Math.min(j, n);
    } else {
      out.push(c);
      i += 1;
    }
  }
  return out.join('');
}

function ktBlankSpan(code, start, end) {
  return code.slice(0, start) + ' '.repeat(end - start) + code.slice(end);
}

function ktLast(qualified) {
  return qualified.slice(qualified.lastIndexOf('.') + 1).trim();
}

// The supertypes after the colon of a class header. Generic arguments and parenthesized parts go first: the primary
// constructor's parameters, and the arguments of a base call such as Base(x), hold colons and commas of their own.
function ktBases(header) {
  let h = header;
  while (/<[^<>]*>/.test(h)) h = h.replace(/<[^<>]*>/g, '');
  while (/\([^()]*\)/.test(h)) h = h.replace(/\([^()]*\)/g, '');
  const colon = h.indexOf(':');
  if (colon === -1) return [];
  const bases = [];
  for (const part of h.slice(colon + 1).split(',')) {
    const m = /^\s*([A-Za-z_][\w$.]*)/.exec(part);
    if (m) bases.push(ktLast(m[1]));
  }
  return bases;
}

function ktRefNames(code) {
  const names = [];
  for (const m of code.matchAll(ktCallRe)) if (!ktCallSkip.has(m[1])) names.push(m[1]);
  for (const m of code.matchAll(ktAnnotationRe)) names.push(ktLast(m[1]));
  return names;
}

// One sorted array per build: index it once per array.
function ktFileIndex(files) {
  let index = ktIndexes.get(files);
  if (!index) {
    index = { paths: new Set(files), byName: new Map() };
    for (const p of files) {
      const base = p.slice(p.lastIndexOf('/') + 1);
      const list = index.byName.get(base);
      if (list) list.push(p);
      else index.byName.set(base, [p]);
    }
    ktIndexes.set(files, index);
  }
  return index;
}

// Kotlin files may hold any declarations, so a class is looked up by its path. Java files in a mixed repo are
// found too: a Kotlin app imports the Java classes next to it.
function ktFindFile(qualified, index) {
  for (const ext of ['.kt', '.java']) {
    const rel = `${qualified.replace(/\./g, '/')}${ext}`;
    if (index.paths.has(rel)) return rel;
    for (const root of ['src/main/kotlin/', 'src/main/java/', 'src/']) {
      if (index.paths.has(root + rel)) return root + rel;
    }
    const tail = `/${rel}`;
    const candidates = index.byName.get(rel.slice(rel.lastIndexOf('/') + 1)) ?? [];
    const hit = candidates.find((p) => p.endsWith(tail));
    if (hit) return hit;
  }
  return null;
}

const kotlinLang = {
  id: 'kotlin',
  exts: ['.kt', '.kts'],
  extract(text) {
    const lines = ktStrip(String(text ?? '')).split('\n');
    const symbols = [];
    const imports = [];
    const refs = [];
    const extended = [];
    const seenRefs = new Set();
    const types = []; // open type bodies, innermost last; a companion object reuses its owner's name
    let pending = null; // a type header whose body may not come
    let depth = 0;
    let parens = 0;

    const addRef = (name, line) => {
      const key = `${line} ${name}`;
      if (seenRefs.has(key)) return;
      seenRefs.add(key);
      refs.push({ name, line });
    };
    const headerDone = (open) => {
      if (open.skip) return;
      for (const base of ktBases(open.header)) {
        extended.push({ name: open.full, base, line: open.line });
        addRef(base, open.line);
      }
    };
    const openBody = (open) => {
      types.push({ full: open.full, bodyDepth: depth, skip: open.skip });
      headerDone(open);
    };

    lines.forEach((code, index) => {
      const line = index + 1;
      // A header with no body ends at its line unless the next line continues it: a ':' or '{' or 'where'.
      if (pending && pending.ready && code.trim() !== '' && !/^\s*(\{|:|where\b)/.test(code)) {
        headerDone(pending);
        pending = null;
      }
      const top = types.at(-1);
      const atMembers = parens === 0 && depth === (top ? top.bodyDepth : 0);
      let refText = code;
      let scanFrom = 0;

      const im = ktImportRe.exec(code);
      if (im) imports.push({ spec: im[1], line, names: im[1].endsWith('*') ? [] : [ktLast(im[1])] });

      if (!pending && atMembers) {
        const type = ktTypeRe.exec(code);
        const fun = type ? null : ktFunRe.exec(code);
        const val = type || fun ? null : ktValRe.exec(code);
        if (type) {
          const named = type[4] !== undefined;
          const companion = /\bcompanion\b/.test(type[2]);
          if (named || (companion && top)) {
            const full = named ? (top ? `${top.full}.${type[4]}` : type[4]) : top.full;
            const skip = named ? types.length >= 2 : top.skip;
            const kind = type[3] === 'interface' ? 'type' : /\benum\b/.test(type[2]) ? 'enum' : 'class';
            if (named && !skip) symbols.push({ name: full, kind, line, exported: !/\b(private|internal)\b/.test(type[2]) });
            pending = { full, skip, line, header: '', ready: false };
            refText = ktBlankSpan(code, type[1].length, type[0].length);
            scanFrom = type[0].length;
          }
        } else if (fun) {
          refText = ktBlankSpan(code, fun[1].length, fun[0].length);
          const receiver = fun[3] ? ktLast(fun[3].replace(/<[^>]*>/g, '')) : null;
          if (!top?.skip) {
            const name = receiver ? `${receiver}.${fun[4]}` : top ? `${top.full}.${fun[4]}` : fun[4];
            const kind = receiver || top ? 'method' : 'fn';
            symbols.push({ name, kind, line, exported: !/\b(private|internal)\b/.test(fun[2]) });
          }
        } else if (val) {
          const isConst = /\bconst\b/.test(val[2]);
          const exported = !/\b(private|internal)\b/.test(val[2]);
          if (!top) {
            symbols.push({ name: val[4], kind: val[3] === 'var' && !isConst ? 'var' : 'const', line, exported });
          } else if (isConst && !top.skip) {
            symbols.push({ name: `${top.full}.${val[4]}`, kind: 'const', line, exported });
          }
        }
      }

      for (const name of ktRefNames(refText)) addRef(name, line);

      for (let k = scanFrom; k < code.length; k += 1) {
        const ch = code[k];
        if (ch === '{') {
          depth += 1;
          if (pending) {
            openBody(pending);
            pending = null;
          }
          continue;
        }
        if (pending) pending.header += ch;
        if (ch === '}') {
          depth -= 1;
          while (types.length && types.at(-1).bodyDepth > depth) types.pop();
        } else if (ch === '(') {
          parens += 1;
        } else if (ch === ')') {
          parens = Math.max(0, parens - 1);
        }
      }
      if (pending) {
        pending.header += ' ';
        pending.ready = parens === 0 && !/[:,(]\s*$/.test(code);
      }
    });
    if (pending) headerDone(pending);
    // A supertype is found when its header closes, which can be after the lines that follow it.
    refs.sort((a, b) => a.line - b.line);

    return { symbols, imports, refs, extends: extended };
  },
  resolve(spec, fromPath, files) {
    if (spec.endsWith('*')) return null;
    const index = ktFileIndex(files);
    const found = ktFindFile(spec, index);
    if (found) return found;
    // A nested class or a top-level member names its file: a.b.C.Inner is found in a/b/C.kt.
    const dot = spec.lastIndexOf('.');
    return dot > 0 ? ktFindFile(spec.slice(0, dot), index) : null;
  },
};

// ---- server/codemap/lang/markdown.js ----
// Markdown: headings become a doc's sections, and the repo paths and backticked names it writes become mentions,
// so a search for some code also finds the docs that explain it. Which mentions are real is decided at build time,
// against the repo's files and symbols.

// file endings a word must have to read as a file name when it has no '/'
const MD_FILE_EXTS = 'js|mjs|cjs|jsx|ts|tsx|mts|cts|py|rb|go|rs|java|kt|kts|cs|swift|php|c|h|cc|cpp|hpp|sql|md|mdx|json|ya?ml|toml|sh|html|css|scss|vue|svelte';
const MD_PATH = new RegExp(`(?:\\.{1,2}/)?[\\w@~.-]+(?:/[\\w@~.-]+)+|[\\w@~-][\\w@~.-]*\\.(?:${MD_FILE_EXTS})(?![\\w-])`, 'g');
const MD_NAME = /^[A-Za-z_$][\w$]*(?:[.#][A-Za-z_$][\w$]*)*$/;
// `doing` or `member` in prose is a word; `fetchCart`, `Cart`, `parse_amount`, `Cart.add` or `fetch()` is code
const MD_CODE = /[a-z0-9][A-Z]|^[A-Z]|[_.#$]/;
const MD_URL = /\b[a-z][a-z0-9+.-]*:\/\/\S+|\bwww\.\S+/gi;

// heading text without its markup: `code`, *emphasis*, [link](target) and closing #s
function mdHeading(s) {
  return s.replace(/\s+#+\s*$/, '').replace(/\[([^\]]*)\]\([^)]*\)/g, '$1').replace(/[`*_]/g, '').trim();
}

function mdPaths(line, n, refs) {
  for (const m of line.replace(MD_URL, ' ').matchAll(MD_PATH)) {
    const p = m[0].replace(/[.,;:!?]+$/, '');
    if (p && !p.endsWith('/')) refs.push({ name: p, line: n, path: true });
  }
}

function mdExtract(text) {
  const out = { symbols: [], imports: [], refs: [], extends: [] };
  if (!text) return out;
  const lines = text.split(/\r?\n/);
  let fence = '', start = 0;
  // front matter is data, and its closing --- would read as a heading underline
  if (/^---\s*$/.test(lines[0])) {
    const close = lines.findIndex((l, i) => i > 0 && /^(---|\.\.\.)\s*$/.test(l));
    if (close > 0) start = close + 1;
  }
  for (let i = start; i < lines.length; i++) {
    const line = lines[i], n = i + 1;
    const f = /^ {0,3}(`{3,}|~{3,})/.exec(line);
    if (f && (!fence || f[1][0] === fence[0] && f[1].length >= fence.length)) { fence = fence ? '' : f[1]; continue; }
    if (fence) { mdPaths(line, n, out.refs); continue; }
    const atx = /^ {0,3}(#{1,6})\s+(.*)$/.exec(line);
    const prev = i > start ? lines[i - 1] : '';
    const underline = /^ {0,3}(=+|-+)\s*$/.exec(line);
    if (atx && mdHeading(atx[2])) {
      out.symbols.push({ name: mdHeading(atx[2]), kind: `h${atx[1].length}`, line: n });
    } else if (underline && prev.trim() && !/^ {0,3}([-*+>#|]|\d+[.)])/.test(prev) && out.symbols.every((s) => s.line !== i)) {
      // Title followed by === or ---: the heading is the line above
      out.symbols.push({ name: mdHeading(prev), kind: underline[1][0] === '=' ? 'h1' : 'h2', line: i });
      continue;
    }
    const plain = line.replace(/<!--.*?-->/g, ' ');
    for (const m of plain.matchAll(/`([^`]+)`/g)) {
      const written = m[1].trim(), name = written.replace(/\(.*\)$/, '');
      if (MD_NAME.test(name) && (name !== written || MD_CODE.test(name))) out.refs.push({ name, line: n });
    }
    mdPaths(plain, n, out.refs);
  }
  // a section runs to the line before the next heading
  out.symbols.sort((a, b) => a.line - b.line);
  const last = lines.length - (lines[lines.length - 1] === '' ? 1 : 0);
  out.symbols.forEach((s, i) => { s.end = i + 1 < out.symbols.length ? out.symbols[i + 1].line - 1 : last; });
  return out;
}

const markdownLang = {
  id: 'md',
  exts: ['.md', '.mdx', '.markdown'],
  // its file is a doc and its symbols are sections
  doc: true,
  extract: mdExtract,
  resolve: () => null,
};

// ---- server/codemap/lang/php.js ----
// PHP: symbols, imports, references and inheritance. Comments and strings are blanked before the tokens are read,
// so a commented-out definition or a string that looks like code never becomes a symbol. A stack of scopes tells a
// method from a closure, and a top-level import from a trait use inside a class.

const PHP_SKIP = /\/\*[\s\S]*?(?:\*\/|$)|\/\/(?:(?!\?>)[^\n])*|#(?!\[)[^\n]*|'(?:[^'\\]|\\[\s\S])*'|"(?:[^"\\]|\\[\s\S])*"|<<<[ \t]*(["']?)([A-Za-z_]\w*)\1\r?\n(?:[\s\S]*?\n)?[ \t]*\2\b/g;
const PHP_TOKEN = /\\?[A-Za-z_\x80-￿][\w\x80-￿]*(?:\\[A-Za-z_\x80-￿][\w\x80-￿]*)*|\$[A-Za-z_\x80-￿][\w\x80-￿]*|\d[\w.]*|'[^']*'|"[^"]*"|::|\?->|->|\S/g;
const PHP_MODS = new Set(['public', 'private', 'protected', 'static', 'final', 'abstract', 'readonly', 'var']);
const PHP_KEYWORDS = new Set(['if', 'elseif', 'while', 'for', 'foreach', 'switch', 'catch', 'match', 'function', 'fn', 'array', 'list', 'isset', 'unset', 'empty', 'echo', 'print', 'return', 'exit', 'die', 'eval', 'declare', 'use', 'include', 'include_once', 'require', 'require_once', 'and', 'or', 'not']);
const PHP_NOT_CLASS = new Set(['class', 'self', 'parent', 'static']);
const PHP_DECL_KIND = new Map([['class', 'class'], ['trait', 'class'], ['interface', 'type'], ['enum', 'enum']]);
const PHP_INCLUDE = new Set(['include', 'include_once', 'require', 'require_once']);
const PHP_NONE = { v: '', p: -1, line: 0 };
const PHP_INDEX = new WeakMap();

function phpAt(toks, k) {
  return k >= 0 && k < toks.length ? toks[k] : PHP_NONE;
}

function phpBlank(s) {
  return s.replace(/[^\n]/g, ' ');
}

// A file without tags is plain code; a template's markup outside the tags is blanked so its words stay out of the map.
function phpCodeOnly(text) {
  if (!text.includes('<?')) return text;
  let out = '';
  let last = 0;
  let code = false;
  for (const m of text.matchAll(/<\?php\b|<\?=|\?>/g)) {
    const seg = text.slice(last, m.index);
    out += (code ? seg : phpBlank(seg)) + phpBlank(m[0]);
    code = m[0] !== '?>';
    last = m.index + m[0].length;
  }
  return out + (code ? text.slice(last) : phpBlank(text.slice(last)));
}

// Strings keep their quotes so the tokenizer still sees a literal; the text is read back from the original.
function phpStrip(text) {
  return phpCodeOnly(text).replace(PHP_SKIP, (m) => (m[0] === '"' || m[0] === "'" ? m[0] + phpBlank(m.slice(1, -1)) + m[0] : phpBlank(m)));
}

function phpTokens(code) {
  const toks = [];
  let line = 1;
  let at = 0;
  for (const m of code.matchAll(PHP_TOKEN)) {
    for (; at < m.index; at++) if (code.charCodeAt(at) === 10) line++;
    toks.push({ v: m[0], p: m.index, line });
  }
  return toks;
}

function phpIsWord(v) {
  return /^\\?[A-Za-z_\x80-￿]/.test(v);
}

function phpLast(name) {
  return name.slice(name.lastIndexOf('\\') + 1);
}

function phpHidden(mods) {
  return mods.includes('private') || mods.includes('protected');
}

// Reads a comma-separated list of names from j. Returns the index after the list.
function phpNameList(toks, j, onName) {
  while (phpIsWord(phpAt(toks, j).v)) {
    onName(phpAt(toks, j));
    j++;
    if (phpAt(toks, j).v === ',') j++;
    else break;
  }
  return j;
}

// `use A\B\C;`, `use A\B\C as D;`, `use A\B\{C, D as E};`, `use function A\f;`, `use A\B, C\D;`.
// Each imported class gets its full spec; names keep the original last segment, not the alias.
function phpUseImports(toks, i, out) {
  let j = i + 1;
  if (/^(function|const)$/i.test(phpAt(toks, j).v)) j++;
  while (phpIsWord(phpAt(toks, j).v)) {
    const head = phpAt(toks, j);
    const prefix = head.v.replace(/^\\/, '');
    j++;
    if (phpAt(toks, j).v === '\\' && phpAt(toks, j + 1).v === '{') {
      j += 2;
      while (phpAt(toks, j).v !== '' && phpAt(toks, j).v !== '}' && phpAt(toks, j).v !== ';') {
        const m = phpAt(toks, j);
        if (phpIsWord(m.v)) {
          out.push({ spec: `${prefix}\\${m.v}`, line: m.line, names: [phpLast(m.v)] });
          j++;
          if (/^as$/i.test(phpAt(toks, j).v)) j += 2;
        } else {
          j++;
        }
      }
      j++;
    } else {
      out.push({ spec: prefix, line: head.line, names: [phpLast(prefix)] });
      if (/^as$/i.test(phpAt(toks, j).v)) j += 2;
    }
    if (phpAt(toks, j).v !== ',') break;
    j++;
  }
  return j;
}

function phpParse(text) {
  const toks = phpTokens(phpStrip(text));
  const symbols = [];
  const imports = [];
  const refs = [];
  const extendsList = [];
  const scopes = [];
  let decl = null; // a class header, from its keyword to its brace
  let nsHeader = false; // `namespace X {` opens a namespace scope, `namespace X;` does not
  let mods = [];

  for (let i = 0; i < toks.length; i++) {
    const { v, line } = toks[i];
    const lower = v.toLowerCase();
    const prev = i > 0 ? toks[i - 1].v : '';
    const scope = scopes[scopes.length - 1];

    if (v === '{') {
      if (decl) {
        scopes.push({ kind: 'class', name: decl.name });
        for (const b of decl.bases) extendsList.push({ name: decl.name, base: b.name, line: b.line });
        decl = null;
      } else {
        scopes.push({ kind: nsHeader ? 'ns' : 'other' });
      }
      nsHeader = false;
      mods = [];
      continue;
    }
    if (v === '}') {
      scopes.pop();
      mods = [];
      continue;
    }
    if (v === ';') {
      nsHeader = false;
      mods = [];
      continue;
    }
    // An attribute's closing bracket ends the modifiers that came before it.
    if (v === ']') {
      mods = [];
      continue;
    }
    if (PHP_MODS.has(lower)) {
      mods.push(lower);
      continue;
    }
    if (lower === 'namespace') {
      nsHeader = true;
      continue;
    }

    const kind = PHP_DECL_KIND.get(lower);
    const nameTok = phpAt(toks, i + 1);
    // Foo::class, $x->class and `new class` are not declarations.
    if (kind && phpIsWord(nameTok.v) && !['extends', 'implements'].includes(nameTok.v.toLowerCase()) && !['::', '->', 'new'].includes(prev)) {
      decl = { name: nameTok.v, bases: [] };
      if (!scope || scope.kind === 'ns') symbols.push({ name: nameTok.v, kind, line: nameTok.line, exported: true });
      mods = [];
      i++;
      continue;
    }

    // Outside a declaration (an anonymous class) the bases are references only.
    if ((lower === 'extends' || lower === 'implements') && phpIsWord(phpAt(toks, i + 1).v)) {
      i = phpNameList(toks, i + 1, (t) => {
        const name = phpLast(t.v);
        refs.push({ name, line: t.line });
        if (decl) decl.bases.push({ name, line: t.line });
      }) - 1;
      continue;
    }

    if (lower === 'function') {
      const fnMods = mods;
      mods = [];
      let j = i + 1;
      if (phpAt(toks, j).v === '&') j++;
      const fnTok = phpAt(toks, j);
      if (phpIsWord(fnTok.v) && phpAt(toks, j + 1).v === '(') {
        if (!scope || scope.kind === 'ns') symbols.push({ name: fnTok.v, kind: 'fn', line: fnTok.line, exported: true });
        else if (scope.kind === 'class') symbols.push({ name: `${scope.name}.${fnTok.v}`, kind: 'method', line: fnTok.line, exported: !phpHidden(fnMods) });
        i = j;
      }
      continue;
    }

    if (lower === 'const') {
      const constMods = mods;
      mods = [];
      if (phpIsWord(nameTok.v) && phpAt(toks, i + 2).v === '=') {
        if (!scope || scope.kind === 'ns') symbols.push({ name: nameTok.v, kind: 'const', line: nameTok.line, exported: true });
        else if (scope.kind === 'class') symbols.push({ name: `${scope.name}.${nameTok.v}`, kind: 'const', line: nameTok.line, exported: !phpHidden(constMods) });
        i++;
      }
      continue;
    }

    if (lower === 'use') {
      if (scope && scope.kind === 'class') {
        i = phpNameList(toks, i + 1, (t) => {
          const base = phpLast(t.v);
          refs.push({ name: base, line: t.line });
          extendsList.push({ name: scope.name, base, line: t.line });
        }) - 1;
      } else if (!scope || scope.kind === 'ns') {
        i = phpUseImports(toks, i, imports) - 1;
      }
      continue;
    }

    // Include paths are literal only; a concatenated path such as __DIR__ . '/x.php' is not read.
    if (PHP_INCLUDE.has(lower)) {
      let j = i + 1;
      if (phpAt(toks, j).v === '(') j++;
      const s = phpAt(toks, j);
      if (s.v[0] === "'" || s.v[0] === '"') imports.push({ spec: text.slice(s.p + 1, s.p + s.v.length - 1), line: s.line, names: [] });
      continue;
    }

    if (lower === 'new') {
      const n = phpAt(toks, i + 1);
      if (phpIsWord(n.v) && !PHP_NOT_CLASS.has(n.v.toLowerCase())) refs.push({ name: phpLast(n.v), line: n.line });
      continue;
    }

    if (phpIsWord(v) && phpAt(toks, i + 1).v === '(' && prev !== 'new') {
      const member = prev === '->' || prev === '?->';
      const isStatic = prev === '::';
      if (isStatic) {
        const cls = phpAt(toks, i - 2);
        if (phpIsWord(cls.v) && !PHP_NOT_CLASS.has(cls.v.toLowerCase())) refs.push({ name: phpLast(cls.v), line: cls.line });
      }
      if (member || isStatic || !PHP_KEYWORDS.has(lower)) refs.push({ name: phpLast(v), line });
    }
  }
  return { symbols, imports, refs, extends: extendsList };
}

// Files are indexed once per list: a build resolves thousands of imports against the same array.
function phpIndex(files) {
  let idx = PHP_INDEX.get(files);
  if (!idx) {
    const byBase = new Map();
    for (const f of files) {
      const base = f.slice(f.lastIndexOf('/') + 1);
      if (!byBase.has(base)) byBase.set(base, []);
      byBase.get(base).push(f);
    }
    idx = { set: new Set(files), byBase };
    PHP_INDEX.set(files, idx);
  }
  return idx;
}

function phpNormalize(path) {
  const out = [];
  for (const seg of path.split('/')) {
    if (seg === '' || seg === '.') continue;
    if (seg === '..') out.pop();
    else out.push(seg);
  }
  return out.join('/');
}

// Namespaces map to paths with PSR-4 guesses: the full path under src/ or the repo root, then a file whose path
// ends with the name, dropping at most the first segment (the vendor or root namespace that the tree does not repeat).
function phpResolve(spec, fromPath, files) {
  const idx = phpIndex(files);
  if (spec.includes('/') || /\.php$/i.test(spec)) {
    const dir = fromPath.slice(0, fromPath.lastIndexOf('/') + 1);
    const p = phpNormalize(spec.startsWith('/') ? spec : dir + spec);
    return idx.set.has(p) ? p : null;
  }
  const segs = spec.split('\\').filter(Boolean);
  for (let k = 0; k < Math.min(segs.length, 2); k++) {
    const sub = segs.slice(k).join('/') + '.php';
    for (const cand of [`src/${sub}`, sub]) if (idx.set.has(cand)) return cand;
    const hit = (idx.byBase.get(sub.slice(sub.lastIndexOf('/') + 1)) || []).find((f) => f.endsWith(`/${sub}`));
    if (hit) return hit;
  }
  return null;
}

const phpLang = {
  id: 'php',
  exts: ['.php'],
  extract(text) {
    return phpParse(text);
  },
  resolve: phpResolve,
};

// ---- server/codemap/lang/python.js ----
// Python symbols, imports, calls and base classes, read from one file's text with no parser. Comments and string
// literals are blanked first, so a commented-out def or a docstring that says "class Foo" never becomes a symbol.
// Blanking keeps every line and column, so the line numbers in the results are the file's own.

const PY_KEYWORDS = new Set([
  'False', 'None', 'True', 'and', 'as', 'assert', 'async', 'await', 'break', 'class', 'continue', 'def', 'del',
  'elif', 'else', 'except', 'finally', 'for', 'from', 'global', 'if', 'import', 'in', 'is', 'lambda', 'nonlocal',
  'not', 'or', 'pass', 'raise', 'return', 'try', 'while', 'with', 'yield',
]);

// A comment, or a string with an optional prefix. Triple quotes come first so that a single-quote pattern cannot
// end a triple-quoted string early.
const PY_LITERAL = /#[^\n]*|(?:(?<!\w)[rRbBuUfF]{1,2})?(?:'''[\s\S]*?'''|"""[\s\S]*?"""|'(?:\\.|[^'\\\n])*'|"(?:\\.|[^"\\\n])*")/g;
const PY_DEF = /^(?:async[ \t]+)?def[ \t]+([A-Za-z_]\w*)/;
const PY_CLASS = /^class[ \t]+([A-Za-z_]\w*)[ \t]*(?:\(([\s\S]*?)\))?[ \t]*:/;
const PY_ASSIGN = /^([A-Za-z_]\w*)[ \t]*(?::[^=\n]*)?=(?!=)/;
const PY_CONSTANT = /^_*[A-Z][A-Z0-9_]*$/;
const PY_DECORATOR = /^[ \t]*@[ \t]*([A-Za-z_][\w.]*)/;
const PY_CALL = /(?<!\w)(?<!\b(?:def|class)[ \t]+)([A-Za-z_]\w*)[ \t]*\(/g;
const PY_FROM = /^from[ \t]+(\.*[A-Za-z_][\w.]*|\.+)[ \t]+import\b([\s\S]*)$/;
const PY_IMPORT = /^import\b([\s\S]*)$/;
const PY_DOTTED = /^(?:[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)*)?$/;

// The resolver runs once per import with the same list, so the lookup tables are built once per list.
const pyIndexes = new WeakMap();

function pyBlank(text) {
  return text.replace(/\r\n?/g, '\n').replace(PY_LITERAL, (token) => token.replace(/[^\n]/g, ' '));
}

function pyBracketDelta(line) {
  let delta = 0;
  for (const char of line) {
    if ('([{'.includes(char)) delta += 1;
    else if (')]}'.includes(char)) delta -= 1;
  }
  return delta;
}

// A statement runs on past its first line while a bracket is open or the line ends in a backslash.
function pyStatement(lines, start) {
  let depth = 0;
  let end = start;
  for (;;) {
    depth += pyBracketDelta(lines[end]);
    const continues = depth > 0 || /\\[ \t]*$/.test(lines[end]);
    if (!continues || end + 1 >= lines.length) break;
    end += 1;
  }
  return { text: lines.slice(start, end + 1).join('\n'), end };
}

function pyNames(raw) {
  const names = raw
    .replace(/[()\\\n]/g, ' ')
    .split(',')
    .map((part) => part.trim().split(/\s+as\s+/)[0])
    .filter(Boolean);
  return names.includes('*') ? [] : names;
}

function pyBases(list) {
  let flat = list;
  while (/\[[^[\]]*\]/.test(flat)) flat = flat.replace(/\[[^[\]]*\]/g, '');
  return flat
    .split(',')
    .map((part) => part.trim())
    .filter((part) => /^[A-Za-z_][\w.]*$/.test(part))
    .map((part) => part.split('.').pop());
}

// A dunder like __init__ is the public constructor of its class, so it counts as exported.
function pyExported(name) {
  return !name.startsWith('_') || name === '__init__';
}

function pyDirOf(path) {
  const cut = path.lastIndexOf('/');
  return cut < 0 ? '' : path.slice(0, cut);
}

function pyIndex(files) {
  if (!files || typeof files !== 'object') return { paths: new Set(), srcPaths: new Map() };
  let index = pyIndexes.get(files);
  if (!index) {
    index = { paths: new Set(files), srcPaths: new Map() };
    for (const file of files) {
      // A src/ layout keeps the package one directory down, so the import names it without that directory.
      if (file.startsWith('src/') && !index.srcPaths.has(file.slice(4))) index.srcPaths.set(file.slice(4), file);
    }
    pyIndexes.set(files, index);
  }
  return index;
}

function pyModuleFile(lookup, base, dotted) {
  if (!dotted) return lookup([base, '__init__.py'].filter(Boolean).join('/'));
  const stem = [base, ...dotted.split('.')].filter(Boolean).join('/');
  return lookup(`${stem}.py`) ?? lookup(`${stem}/__init__.py`);
}

const pythonLang = {
  id: 'python',
  exts: ['.py'],

  extract(text) {
    const lines = pyBlank(String(text ?? '')).split('\n');
    const symbols = [];
    const imports = [];
    const extendsList = [];
    const refs = [];
    let owner = null; // the module-level class whose body the current statement may sit in

    let i = 0;
    while (i < lines.length) {
      if (lines[i].trim() === '') {
        i += 1;
        continue;
      }
      const { text: statement, end } = pyStatement(lines, i);
      const line = i + 1;
      const indent = /^[ \t]*/.exec(lines[i])[0];
      i = end + 1;
      const head = statement.trimStart();

      if (indent === '') owner = null;
      else if (owner && owner.bodyIndent === null) owner.bodyIndent = indent;

      const fromImport = PY_FROM.exec(head);
      if (fromImport) {
        const names = pyNames(fromImport[2]);
        imports.push(names.length ? { spec: fromImport[1], line, names } : { spec: fromImport[1], line });
        continue;
      }
      const plainImport = PY_IMPORT.exec(head);
      if (plainImport) {
        for (const part of plainImport[1].split(',')) {
          const spec = /^\s*([A-Za-z_][\w.]*)/.exec(part);
          if (spec) imports.push({ spec: spec[1], line });
        }
        continue;
      }

      if (indent === '') {
        const classHead = PY_CLASS.exec(head);
        if (classHead) {
          const [, name, bases = ''] = classHead;
          owner = { name, bodyIndent: null };
          symbols.push({ name, kind: 'class', line, exported: pyExported(name) });
          for (const base of pyBases(bases)) extendsList.push({ name, base, line });
          continue;
        }
      }

      const def = PY_DEF.exec(head);
      if (def && indent === '') {
        symbols.push({ name: def[1], kind: 'fn', line, exported: pyExported(def[1]) });
      } else if (def && owner && indent === owner.bodyIndent) {
        symbols.push({ name: `${owner.name}.${def[1]}`, kind: 'method', line, exported: pyExported(def[1]) });
      } else if (indent === '') {
        const assign = PY_ASSIGN.exec(head);
        if (assign && !PY_KEYWORDS.has(assign[1])) {
          symbols.push({
            name: assign[1],
            kind: PY_CONSTANT.test(assign[1]) ? 'const' : 'var',
            line,
            exported: pyExported(assign[1]),
          });
        }
      }
    }

    lines.forEach((code, index) => {
      const seen = new Set();
      const add = (name) => {
        if (seen.has(name)) return;
        seen.add(name);
        refs.push({ name, line: index + 1 });
      };
      const decorator = PY_DECORATOR.exec(code);
      if (decorator) add(decorator[1].split('.').pop());
      for (const call of code.matchAll(PY_CALL)) {
        if (!PY_KEYWORDS.has(call[1])) add(call[1]);
      }
    });

    return { symbols, imports, refs, extends: extendsList };
  },

  resolve(spec, fromPath, files) {
    if (typeof spec !== 'string') return null;
    const dots = /^\.*/.exec(spec)[0].length;
    const dotted = spec.slice(dots);
    if (!PY_DOTTED.test(dotted) || (dots === 0 && dotted === '')) return null;
    const index = pyIndex(files);
    const exact = (path) => (index.paths.has(path) ? path : null);
    if (dots === 0) {
      return pyModuleFile(exact, '', dotted) ?? pyModuleFile((path) => index.srcPaths.get(path) ?? null, '', dotted);
    }
    let base = pyDirOf(String(fromPath ?? ''));
    for (let up = 1; up < dots; up += 1) {
      if (base === '') return null;
      base = pyDirOf(base);
    }
    return pyModuleFile(exact, base, dotted);
  },
};

// ---- server/codemap/lang/ruby.js ----
// Ruby symbols, requires, includes and superclasses, read from one file's text with no parser. Comments, =begin
// blocks, heredoc bodies and string literals are blanked first, so a def inside a heredoc never becomes a symbol.
// Blanking keeps every column and line, so the line numbers in the results are the file's own.

const RB_KEYWORDS = new Set([
  'BEGIN', 'END', 'alias', 'and', 'begin', 'break', 'case', 'class', 'def', 'defined?', 'do', 'else', 'elsif', 'end',
  'ensure', 'false', 'for', 'if', 'in', 'module', 'next', 'nil', 'not', 'or', 'redo', 'rescue', 'retry', 'return',
  'self', 'super', 'then', 'true', 'undef', 'unless', 'until', 'when', 'while', 'yield',
]);

// A comment, a string, a %-literal, a regex, or the start of a heredoc. Each one stays on its line; the body of a
// heredoc spans lines and is blanked by rbStrip.
const RB_LITERAL = /#.*$|'(?:\\.|[^'\\])*'?|"(?:\\.|[^"\\])*"?|`(?:\\.|[^`\\])*`?|%[qQwWiIsr]?(?:\((?:\\.|[^)\\])*\)|\[(?:\\.|[^\]\\])*\]|\{(?:\\.|[^}\\])*\}|<(?:\\.|[^>\\])*>|\|(?:\\.|[^|\\])*\||!(?:\\.|[^!\\])*!)|(?<![\w)\]])\/(?![\s=])(?:\\.|[^\/\\])*\/[a-z]*|<<[~-]?(?:(["'`])[A-Za-z_]\w*\1|[A-Z_]\w*)/g;
const RB_WORD = /[A-Za-z_]\w*[?!]?/g;
const RB_CLASS = /^class\s+((?:::)?[A-Z]\w*(?:::[A-Z]\w*)*)(?:\s*<\s*((?:::)?[A-Z]\w*(?:::[A-Z]\w*)*))?/;
const RB_MODULE = /^module\s+((?:::)?[A-Z]\w*(?:::[A-Z]\w*)*)/;
const RB_DEF = /^def\s+(?:self\.|[A-Z]\w*\.)?([A-Za-z_]\w*[?!=]?)/;
// An endless method, `def name(args) = expr`, has no end keyword; a setter `def name=(v)` is not one.
const RB_ENDLESS = /^def\s+(?:self\.|[A-Z]\w*\.)?[^\s(]+(?:\s*\([^)]*\))?\s+=(?![=~>])/;
const RB_BLOCK_WORDS = new Set(['if', 'unless', 'while', 'until', 'case', 'begin', 'for']);
const RB_REQUIRE_WORDS = new Set(['require', 'require_relative', 'load']);
// `Name.new` names the constant; `name(` names the call. The second alternative skips a def's own name.
const RB_REF = /(?<![\w@$])((?:[A-Z]\w*::)*[A-Z]\w*)\.new\b|(?<![\w@$])(?<!\bdef\s+(?:self\.|[A-Z]\w*\.)?)([A-Za-z_]\w*[?!]?)\(/g;
const RB_INCLUDE = /^\s*((?:::)?[A-Z]\w*(?:::[A-Z]\w*)*)\s*$/;

// The resolver runs once per require with the same list, so the set is built once per list.
const rbFileSets = new WeakMap();

// Keeps the length of a token so that columns in the stripped line still match the raw line. A string keeps its
// quotes, so `"x" if y` still reads as a modifier after the string.
function rbMask(token) {
  if (token.length < 2) return token;
  const last = token[token.length - 1];
  return token[0] + ' '.repeat(token.length - 2) + (/\w/.test(last) ? ' ' : last);
}

function rbStripLine(line, heredocs) {
  return line.replace(RB_LITERAL, (token) => {
    if (token.startsWith('<<')) {
      heredocs.push(token.replace(/^<<[~-]?|["'`]/g, ''));
      return ' '.repeat(token.length);
    }
    if (token.startsWith('#')) return ' '.repeat(token.length);
    return rbMask(token);
  });
}

// A heredoc is taken only when its terminator line exists; a stray `<<CONST` must not blank the rest of the file.
function rbStrip(lines) {
  const pending = []; // terminators of heredocs whose bodies have started, in order
  let inComment = false;
  let ended = false;
  return lines.map((raw, index) => {
    const blank = ' '.repeat(raw.length);
    if (ended) return blank;
    if (pending.length > 0) {
      if (raw.trim() === pending[0]) pending.shift();
      return blank;
    }
    if (inComment) {
      if (/^=end\b/.test(raw)) inComment = false;
      return blank;
    }
    if (/^=begin\b/.test(raw)) {
      inComment = true;
      return blank;
    }
    if (/^__END__\s*$/.test(raw)) {
      ended = true;
      return blank;
    }
    const heredocs = [];
    const code = rbStripLine(raw, heredocs);
    for (const id of heredocs) {
      if (lines.slice(index + 1).some((later) => later.trim() === id)) pending.push(id);
    }
    return code;
  });
}

// Identifiers that are not keywords here: after a dot (a method), after a colon (a symbol), or as a hash label.
function rbWords(line) {
  const words = [];
  for (const match of line.matchAll(RB_WORD)) {
    const word = match[0];
    const at = match.index;
    const before = line[at - 1];
    if (before === '.' || before === ':' || before === '@' || before === '$') continue;
    if (line[at + word.length] === ':' && line[at + word.length + 1] !== ':') continue;
    words.push({ word, at });
  }
  return words;
}

// A keyword that opens a block only starts a statement; after a value it is a modifier (`x if y`).
function rbStartsStatement(line, at) {
  const before = line.slice(0, at).trimEnd();
  return before === '' || /(?:[=(\[{,;&|!<>+\-*\/%?]|\b(?:then|else|do))$/.test(before);
}

function rbLast(name) {
  return name.split('::').pop();
}

// A def is a symbol only when every open block around it is a class, module or singleton class.
function rbScopeOnly(stack) {
  return stack.every((block) => block.type === 'class' || block.type === 'module' || block.type === 'sclass');
}

// The class or module a method belongs to. A singleton class is transparent: `class << self` defines the
// class's own methods.
function rbOwner(stack) {
  for (let k = stack.length - 1; k >= 0; k -= 1) {
    if (stack[k].type === 'sclass') continue;
    return stack[k].type === 'class' || stack[k].type === 'module' ? stack[k] : null;
  }
  return null;
}

function rbScan(raw, code) {
  const symbols = [];
  const imports = [];
  const refs = [];
  const extendsList = [];
  const stack = [];

  code.forEach((line, index) => {
    const number = index + 1;
    const constant = /^\s*([A-Z]\w*)\s*=(?![=~>])/.exec(line);
    if (constant && rbScopeOnly(stack)) {
      const owner = rbOwner(stack);
      const name = owner ? `${owner.name}.${constant[1]}` : constant[1];
      symbols.push({ name, kind: 'const', line: number, exported: true });
    }

    for (const { word, at } of rbWords(line)) {
      const rest = line.slice(at);
      if (word === 'end') {
        stack.pop();
      } else if (word === 'class') {
        if (/^class\s*<</.test(rest)) {
          stack.push({ type: 'sclass', name: '' });
        } else {
          const head = RB_CLASS.exec(rest);
          const name = head ? rbLast(head[1]) : '';
          if (head && rbScopeOnly(stack)) symbols.push({ name, kind: 'class', line: number, exported: true });
          if (head && head[2]) extendsList.push({ name, base: rbLast(head[2]), line: number });
          stack.push({ type: 'class', name });
        }
      } else if (word === 'module') {
        const head = RB_MODULE.exec(rest);
        const name = head ? rbLast(head[1]) : '';
        if (head && rbScopeOnly(stack)) symbols.push({ name, kind: 'module', line: number, exported: true });
        stack.push({ type: 'module', name });
      } else if (word === 'def') {
        const head = RB_DEF.exec(rest);
        if (head && rbScopeOnly(stack)) {
          const owner = rbOwner(stack);
          const symbol = owner
            ? { name: `${owner.name}.${head[1]}`, kind: 'method' }
            : { name: head[1], kind: 'fn' };
          symbols.push({ ...symbol, line: number, exported: true });
        }
        if (!RB_ENDLESS.test(rest)) stack.push({ type: 'def', name: '' });
      } else if (word === 'do') {
        // `while x do` and `for x in y do` share one end with the loop keyword.
        if (!/\b(?:while|until|for)\b/.test(line.slice(0, at))) stack.push({ type: 'block', name: '' });
      } else if (RB_BLOCK_WORDS.has(word) && rbStartsStatement(line, at)) {
        stack.push({ type: 'block', name: '' });
      } else if (RB_REQUIRE_WORDS.has(word) && rbStartsStatement(line, at)) {
        // The spec is a string literal, which the stripped line has blanked; the raw line keeps it at the same columns.
        const arg = /^\s*\(?\s*(['"])([^'"]+)\1/.exec(raw[index].slice(at + word.length));
        if (arg) imports.push({ spec: arg[2], line: number });
      } else if ((word === 'include' || word === 'extend') && rbStartsStatement(line, at)) {
        const owner = rbOwner(stack);
        if (owner && owner.name) {
          for (const part of line.slice(at + word.length).split(',')) {
            const mod = RB_INCLUDE.exec(part);
            if (mod) extendsList.push({ name: owner.name, base: rbLast(mod[1]), line: number });
          }
        }
      }
    }

    const seen = new Set();
    const add = (name) => {
      if (seen.has(name)) return;
      seen.add(name);
      refs.push({ name, line: number });
    };
    for (const match of line.matchAll(RB_REF)) {
      if (match[1]) {
        add(rbLast(match[1]));
      } else if (match[2] !== 'new' && (line[match.index - 1] === '.' || !RB_KEYWORDS.has(match[2]))) {
        add(match[2]);
      }
    }
  });

  return { symbols, imports, refs, extends: extendsList };
}

function rbFileSet(files) {
  if (!files || typeof files !== 'object') return new Set();
  let set = rbFileSets.get(files);
  if (!set) {
    set = new Set(files);
    rbFileSets.set(files, set);
  }
  return set;
}

function rbDirOf(path) {
  const cut = path.lastIndexOf('/');
  return cut < 0 ? '' : path.slice(0, cut);
}

// Joins and removes `.` and `..`; null when the path climbs above the repository root.
function rbNormal(path) {
  if (path.startsWith('/')) return null;
  const parts = [];
  for (const part of path.split('/')) {
    if (part === '' || part === '.') continue;
    if (part === '..') {
      if (parts.length === 0) return null;
      parts.pop();
      continue;
    }
    parts.push(part);
  }
  return parts.join('/');
}

const rubyLang = {
  id: 'ruby',
  exts: ['.rb'],

  extract(text) {
    const raw = String(text ?? '').replace(/\r\n?/g, '\n').split('\n');
    return rbScan(raw, rbStrip(raw));
  },

  // The spec does not say whether it came from require or require_relative, so the file's own directory is tried
  // first, then lib/, then the root. A spec that starts with a dot is always relative to the file.
  resolve(spec, fromPath, files) {
    if (typeof spec !== 'string' || spec === '' || spec.startsWith('/')) return null;
    const names = rbFileSet(files);
    const dir = rbDirOf(String(fromPath ?? ''));
    const bases = spec.startsWith('.') ? [dir] : [dir, 'lib', ''];
    for (const base of bases) {
      const joined = rbNormal([base, spec].filter(Boolean).join('/'));
      if (!joined) continue;
      const file = joined.endsWith('.rb') ? joined : `${joined}.rb`;
      if (names.has(file)) return file;
    }
    return null;
  },
};

// ---- server/codemap/lang/rust.js ----
// Rust: fns, types, traits, enums, consts, statics and modules; impl and trait members as Type.name;
// use and mod declarations as imports; call refs; and trait impls as extends. Comments (nested block
// comments included), strings, raw strings and char literals are blanked first, so a commented-out fn or
// a string such as "struct Fake" never becomes a symbol.

// Keywords and std constructors: a call to one of these never names a repo symbol.
const RS_SKIP = new Set([
  'Err', 'Ok', 'Self', 'Some', 'as', 'async', 'await', 'break', 'const', 'continue', 'crate', 'dyn', 'else',
  'enum', 'extern', 'false', 'fn', 'for', 'if', 'impl', 'in', 'let', 'loop', 'match', 'mod', 'move', 'mut',
  'pub', 'ref', 'return', 'self', 'static', 'struct', 'super', 'trait', 'true', 'type', 'unsafe', 'use', 'where',
  'while',
]);

// Built once per file list: resolve runs once per import over the same list.
const rsSetMemo = new WeakMap();

const RS_KIND = { fn: 'fn', struct: 'type', enum: 'enum', trait: 'type', type: 'type', const: 'const', static: 'var' };

const RS_CALL = /(?<!\w)((?:[A-Za-z_]\w*\s*::\s*)*)([A-Za-z_]\w*)\s*\(/g;
const RS_MACRO = /(?<!\w)([A-Za-z_]\w*)\s*!\s*[([{]/g;
const RS_DECL = /(\bfn\s+)([A-Za-z_]\w*)/;
const RS_HEAD = /^(pub(?:\s*\([^)]*\))?\s+)?(?:(?:const|async|unsafe|default|extern(?:\s*"")?)\s+)*(fn|struct|enum|trait|type|const|static|mod|impl)\b(.*)$/;
const RS_USE = /^(?:pub(?:\s*\([^)]*\))?\s+)?use\s+/;
const RS_RAW = /(?:b|c)?r(#*)"/y;
const RS_CHAR = /'(?:\\(?:u\{[0-9a-fA-F_]*\}|x[0-9a-fA-F]{2}|[^\n])|[\uD800-\uDBFF][\uDC00-\uDFFF]|[^'\\\n])'/y;

function rsBlank(s) {
  return s.replace(/[^\n]/g, ' ');
}

function rsBlockEnd(text, i) {
  let depth = 0;
  let j = i;
  while (j < text.length) {
    if (text[j] === '/' && text[j + 1] === '*') {
      depth++;
      j += 2;
    } else if (text[j] === '*' && text[j + 1] === '/') {
      depth--;
      j += 2;
      if (depth === 0) return j;
    } else {
      j++;
    }
  }
  return text.length;
}

// One lexical unit at i: the text to keep in the code view and where it ends. Anything that is not a
// comment, string or char literal is one character, so a lifetime such as 'a passes through.
function rsSpan(text, i) {
  const c = text[i];
  const next = text[i + 1];
  if (c === '/' && next === '/') {
    const eol = text.indexOf('\n', i);
    const end = eol < 0 ? text.length : eol;
    return { end, out: rsBlank(text.slice(i, end)) };
  }
  if (c === '/' && next === '*') {
    const end = rsBlockEnd(text, i);
    return { end, out: rsBlank(text.slice(i, end)) };
  }
  if (c === '"') {
    let j = i + 1;
    while (j < text.length && text[j] !== '"') j += text[j] === '\\' ? 2 : 1;
    const closed = j < text.length;
    const body = text.slice(i + 1, closed ? j : text.length);
    return { end: closed ? j + 1 : text.length, out: `"${rsBlank(body)}${closed ? '"' : ''}` };
  }
  if (c === 'r' || c === 'b' || c === 'c') {
    RS_RAW.lastIndex = i;
    const m = RS_RAW.exec(text);
    if (m && !/\w/.test(text[i - 1] ?? '')) {
      const bodyStart = i + m[0].length;
      const close = `"${m[1]}`;
      const at = text.indexOf(close, bodyStart);
      const bodyEnd = at < 0 ? text.length : at;
      return {
        end: at < 0 ? text.length : at + close.length,
        out: m[0] + rsBlank(text.slice(bodyStart, bodyEnd)) + (at < 0 ? '' : close),
      };
    }
  }
  if (c === "'") {
    RS_CHAR.lastIndex = i;
    const m = RS_CHAR.exec(text);
    if (m) return { end: i + m[0].length, out: `'${rsBlank(m[0].slice(1, -1))}'` };
  }
  return { end: i + 1, out: c };
}

function rsLex(text) {
  let code = '';
  for (let i = 0; i < text.length; ) {
    const span = rsSpan(text, i);
    code += span.out;
    i = span.end;
  }
  return code.split('\n');
}

function rsDepthDelta(line) {
  let d = 0;
  for (const ch of line) {
    if (ch === '{' || ch === '(' || ch === '[') d++;
    else if (ch === '}' || ch === ')' || ch === ']') d--;
  }
  return d;
}

function rsHead(line) {
  const m = RS_HEAD.exec(line.trim());
  return m ? { isPub: m[1] !== undefined, kw: m[2], rest: m[3] } : null;
}

function rsName(kw, rest) {
  const re = kw === 'static' ? /^\s+(?:mut\s+)?([A-Za-z_]\w*)/ : /^\s+([A-Za-z_]\w*)/;
  const m = re.exec(rest);
  return m ? m[1] : null;
}

// The text from the line at i up to the first line that matches stop, joined on one line, and that line's
// index. Headers and use lists can run over several lines; the cap keeps a file with no closing token from
// scanning on.
function rsGather(code, i, stop) {
  let text = '';
  let j = i;
  for (; j < code.length && j < i + 100; j++) {
    text += ` ${code[j]}`;
    if (stop.test(code[j])) break;
  }
  return { text, last: j };
}

function rsJoinPath(a, b) {
  return a && b ? `${a}::${b}` : a || b;
}

function rsLast(path) {
  const k = path.lastIndexOf('::');
  return k < 0 ? path : path.slice(k + 2);
}

function rsSplitTop(s) {
  const parts = [];
  let depth = 0;
  let cur = '';
  for (const ch of s) {
    if (ch === '{') depth++;
    else if (ch === '}') depth--;
    if (ch === ',' && depth === 0) {
      parts.push(cur);
      cur = '';
    } else {
      cur += ch;
    }
  }
  parts.push(cur);
  return parts;
}

// Brace lists expand one level per call; a leaf names its local binding (the alias when there is one).
// self names the prefix module itself, and a glob binds names the extractor cannot list.
function rsUseEntries(prefix, body, at, imports) {
  for (const part of rsSplitTop(body)) {
    const item = part.trim();
    const open = item.indexOf('{');
    if (open >= 0) {
      const head = item.slice(0, open).replace(/::\s*$/, '').trim();
      rsUseEntries(rsJoinPath(prefix, head), item.slice(open + 1, item.lastIndexOf('}')), at, imports);
    } else if (item) {
      const alias = /^(.+?)\s+as\s+(\w+)$/.exec(item);
      const path = alias ? alias[1] : item;
      if (path === '*' || path.endsWith('::*')) {
        imports.push({ spec: rsJoinPath(prefix, path.slice(0, Math.max(0, path.length - 3))), line: at });
        continue;
      }
      const spec = path === 'self' ? prefix : rsJoinPath(prefix, path);
      const name = alias ? alias[2] : rsLast(spec);
      const entry = { spec, line: at };
      if (name !== '_') entry.names = [name];
      imports.push(entry);
    }
  }
}

function rsUse(code, i, at, imports) {
  const full = rsGather(code, i, /;/).text.trimStart().replace(RS_USE, '');
  const semi = full.indexOf(';');
  rsUseEntries('', semi < 0 ? full : full.slice(0, semi), at, imports);
}

// Skips one balanced <...> group at the start of text.
function rsSkipAngles(text) {
  if (!text.startsWith('<')) return text;
  let depth = 0;
  for (let k = 0; k < text.length; k++) {
    if (text[k] === '<') depth++;
    else if (text[k] === '>' && --depth === 0) return text.slice(k + 1);
  }
  return '';
}

// The last identifier of a type path, with generic arguments and lifetimes dropped:
// fmt::Display, &'a mut Foo<T> and Vec<T> name Display, Foo and Vec.
function rsTypeName(text) {
  let flat = '';
  let depth = 0;
  for (const ch of text) {
    if (ch === '<') depth++;
    else if (ch === '>') depth = Math.max(0, depth - 1);
    else if (depth === 0) flat += ch;
  }
  const names = flat.replace(/'\w+/g, ' ').match(/[A-Za-z_]\w*/g);
  return names ? names[names.length - 1] : '';
}

// An impl header: 'Trait for Type' gives the trait as the base. Where clauses are not part of either.
function rsImplHeader(text) {
  const s = rsSkipAngles(text.trimStart());
  const cut = s.search(/\bwhere\b/);
  const head = cut < 0 ? s : s.slice(0, cut);
  const f = /\bfor\b/.exec(head);
  if (!f) return { type: rsTypeName(head), trait: '' };
  return { type: rsTypeName(head.slice(f.index + 3)), trait: rsTypeName(head.slice(0, f.index)) };
}

// Module-level items. An inline mod body and its items are left out: test modules would fill the map
// with helpers, and the API a repo exposes sits at the top of its files. An item that opens a body returns
// the body and the line its { sits on, since a header can run over several lines.
function rsItem(code, i, head, out) {
  const at = i + 1;
  const name = head.kw === 'impl' ? null : rsName(head.kw, head.rest);
  if (head.kw !== 'impl' && (!name || name === '_')) return null;
  const { text: full, last } = rsGather(code, i, /[{;]/);
  const stop = full.search(/[{;]/);
  const opens = stop >= 0 && full[stop] === '{';
  if (head.kw === 'impl') {
    if (!opens) return null;
    const { type, trait } = rsImplHeader(full.slice(full.search(/\bimpl\b/) + 4, stop));
    if (trait && type) out.extends.push({ name: type, base: trait, line: at });
    return { line: last, body: { kind: 'impl', name: type } };
  }
  if (head.kw === 'mod') {
    out.symbols.push({ name, kind: 'module', line: at, exported: head.isPub });
    if (stop >= 0 && full[stop] === ';') out.imports.push({ spec: name, line: at, names: [name] });
    return opens ? { line: last, body: { kind: 'mod' } } : null;
  }
  out.symbols.push({ name, kind: RS_KIND[head.kw], line: at, exported: head.isPub });
  return head.kw === 'trait' && opens ? { line: last, body: { kind: 'trait', name, exported: head.isPub } } : null;
}

// Direct lines of an impl or trait body: its fns are methods, its consts are Type.NAME consts.
function rsMember(at, top, head, out) {
  if (!top.name || (head.kw !== 'fn' && head.kw !== 'const')) return;
  const name = rsName(head.kw, head.rest);
  if (!name) return;
  const exported = top.kind === 'trait' ? top.exported : head.isPub;
  out.symbols.push({
    name: `${top.name}.${name}`,
    kind: head.kw === 'fn' ? 'method' : 'const',
    line: at,
    exported,
  });
}

// Calls, macro calls, and the owner of a path call (Name::new( gives new and Name). A declared fn name is
// not a call, so it is blanked first.
function rsCalls(line, at, refs) {
  const scan = line.replace(RS_DECL, (_, kw, name) => kw + ' '.repeat(name.length));
  const seen = new Set();
  const add = (name) => {
    if (!name || RS_SKIP.has(name) || seen.has(name)) return;
    seen.add(name);
    refs.push({ name, line: at });
  };
  for (const m of scan.matchAll(RS_CALL)) {
    add(m[2]);
    add(m[1].split('::').map((s) => s.trim()).filter(Boolean).pop());
  }
  for (const m of scan.matchAll(RS_MACRO)) add(m[1]);
}

function rsDirname(p) {
  const k = p.lastIndexOf('/');
  return k < 0 ? '' : p.slice(0, k);
}

function rsJoin(...parts) {
  return parts.filter(Boolean).join('/');
}

function rsFileSet(files) {
  let set = rsSetMemo.get(files);
  if (!set) {
    set = new Set(files);
    rsSetMemo.set(files, set);
  }
  return set;
}

// The src directory above fromPath: the nearest ancestor that holds a lib.rs or main.rs.
function rsCrateRoot(fromPath, set) {
  for (let dir = rsDirname(fromPath); ; dir = rsDirname(dir)) {
    if (set.has(rsJoin(dir, 'lib.rs')) || set.has(rsJoin(dir, 'main.rs'))) return dir;
    if (dir === '') break;
  }
  return 'src';
}

// The directory holding the modules declared inside fromPath: a file x.rs owns x/, a mod.rs or crate
// root owns its own directory.
function rsSelfDir(fromPath) {
  const file = fromPath.slice(fromPath.lastIndexOf('/') + 1);
  const dir = rsDirname(fromPath);
  if (file === 'mod.rs' || file === 'lib.rs' || file === 'main.rs') return dir;
  return rsJoin(dir, file.replace(/\.rs$/, ''));
}

// The file of a module at stem: stem.rs or stem/mod.rs. A crate root (reached by crate:: or super::
// with no more segments) is lib.rs or main.rs in stem.
function rsModuleAt(stem, isRoot, set) {
  const hits = stem ? [`${stem}.rs`, `${stem}/mod.rs`] : [];
  if (isRoot) hits.push(rsJoin(stem, 'lib.rs'), rsJoin(stem, 'main.rs'));
  return hits.find((f) => set.has(f)) ?? null;
}

const rustLang = {
  id: 'rust',
  exts: ['.rs'],
  extract(text) {
    const code = rsLex(text);
    const out = { symbols: [], imports: [], refs: [], extends: [] };
    // stack holds the open impl, trait and mod bodies. A body opens one level deeper than the line its {
    // sits on, and its members sit at that level. opening maps a line index to a body that opens there.
    const stack = [];
    const opening = new Map();
    let depth = 0;
    for (let i = 0; i < code.length; i++) {
      const line = code[i];
      const at = i + 1;
      const d0 = depth;
      depth = Math.max(0, d0 + rsDepthDelta(line));
      if (opening.has(i)) {
        stack.push({ ...opening.get(i), depth: d0 + 1 });
        opening.delete(i);
      }
      const top = stack[stack.length - 1];
      if (!/^\s*#!?\[/.test(line)) rsCalls(line, at, out.refs);
      if (!top && d0 === 0) {
        if (RS_USE.test(line.trim())) rsUse(code, i, at, out.imports);
        else {
          const head = rsHead(line);
          const opened = head ? rsItem(code, i, head, out) : null;
          if (opened?.line === i) stack.push({ ...opened.body, depth: d0 + 1 });
          else if (opened) opening.set(opened.line, opened.body);
        }
      } else if (top && top.kind !== 'mod' && d0 === top.depth) {
        const head = rsHead(line);
        if (head) rsMember(at, top, head, out);
      }
      while (stack.length && depth < stack[stack.length - 1].depth) stack.pop();
    }
    return out;
  },
  // A use path or mod name resolves through crate::, self::, super:: or a bare name. A bare name is first
  // looked up beside fromPath, then at the crate root (edition 2015 paths). Anything else is an external crate.
  resolve(spec, fromPath, files) {
    const set = rsFileSet(files);
    const segs = spec.split('::').filter(Boolean);
    if (segs.length === 0) return null;
    const srcRoot = rsCrateRoot(fromPath, set);
    // Only crate:: and super:: may name the root file itself; a bare or self:: path must go through a module.
    const rootOk = segs[0] === 'crate' || segs[0] === 'super';
    let bases = [rsSelfDir(fromPath), srcRoot];
    let tail = segs;
    if (segs[0] === 'crate') {
      bases = [srcRoot];
      tail = segs.slice(1);
    } else if (segs[0] === 'self' || segs[0] === 'super') {
      let base = rsSelfDir(fromPath);
      while (tail[0] === 'self' || tail[0] === 'super') {
        if (tail[0] === 'super') {
          if (base === srcRoot) return null;
          base = rsDirname(base);
        }
        tail = tail.slice(1);
      }
      bases = [base];
    }
    // The longest module path wins: use a::b::Item finds a/b.rs before a.rs. A path that ends in an
    // item of the base module (k = 0) only counts after crate:: or super::.
    const lowest = rootOk ? 0 : 1;
    for (const base of bases) {
      for (let k = tail.length; k >= lowest; k--) {
        const found = rsModuleAt(rsJoin(base, tail.slice(0, k).join('/')), k === 0, set);
        if (found) return found;
      }
    }
    return null;
  },
};

// ---- server/codemap/lang/sql.js ----
// SQL: tables, views, functions, procedures, indexes, types and triggers, and the tables and functions a statement
// reads or writes. Comments and '' strings are blanked first. A declared name is never also a reference to itself,
// so the tokens that name a declaration are marked before the references are read.

const SQL_SKIP = /--[^\n]*|\/\*[\s\S]*?(?:\*\/|$)|'(?:[^']|'')*'/g;
const SQL_TOKEN = /"([^"\n]*)"|`([^`\n]*)`|[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)*|\d[\w.]*|'[^']*'|\S/g;
const SQL_KIND = new Map([['table', 'table'], ['view', 'type'], ['function', 'fn'], ['procedure', 'fn'], ['index', 'var'], ['type', 'type'], ['trigger', 'fn']]);
const SQL_MODS = new Set(['or', 'replace', 'temp', 'temporary', 'unlogged', 'materialized', 'unique', 'global', 'local', 'recursive']);
const SQL_OPTIONAL = new Set(['if', 'not', 'exists', 'only', 'concurrently']);
const SQL_REF_KW = new Set(['from', 'join', 'into', 'update', 'references', 'table']);
const SQL_NOT_TARGET = new Set(['select', 'set', 'values', 'lateral', 'with', 'on', 'where', 'as', 'dual']);
// Keywords and builtins that take a parenthesis. The type names and DDL keywords (check, key, unique) only appear
// this way in column and table definitions, never as a call.
const SQL_NOT_CALL = new Set(['count', 'sum', 'max', 'min', 'coalesce', 'now', 'lower', 'upper', 'length', 'substr', 'concat', 'cast', 'exists', 'in', 'any', 'all', 'values', 'select', 'insert', 'update', 'delete', 'check', 'primary', 'key', 'unique', 'foreign', 'constraint', 'default', 'using', 'on', 'as', 'over', 'filter', 'returning', 'where', 'with', 'when', 'not', 'and', 'or', 'is', 'like', 'between', 'interval', 'array', 'enum', 'numeric', 'decimal', 'varchar', 'char', 'character', 'timestamp', 'time', 'bit', 'if', 'from', 'join', 'into', 'references', 'table']);
const SQL_INDEX = new WeakMap();

function sqlBlank(s) {
  return s.replace(/[^\n]/g, ' ');
}

function sqlStrip(text) {
  return text.replace(/\r\n?/g, '\n').replace(SQL_SKIP, (m) => (m[0] === "'" ? `'${sqlBlank(m.slice(1, -1))}'` : sqlBlank(m)));
}

function sqlTokens(code) {
  const toks = [];
  let line = 1;
  let at = 0;
  for (const m of code.matchAll(SQL_TOKEN)) {
    for (; at < m.index; at++) if (code.charCodeAt(at) === 10) line++;
    if (m[1] !== undefined || m[2] !== undefined) toks.push({ v: m[1] ?? m[2], w: true, line });
    else toks.push({ v: m[0], w: /^[A-Za-z_]/.test(m[0]), line });
  }
  return toks;
}

function sqlLow(t) {
  return t ? t.v.toLowerCase() : '';
}

function sqlLast(name) {
  return name.slice(name.lastIndexOf('.') + 1);
}

function sqlSkipOptional(toks, k) {
  while (toks[k] && toks[k].w && SQL_OPTIONAL.has(sqlLow(toks[k]))) k++;
  return k;
}

function sqlParse(text) {
  const code = sqlStrip(text);
  const toks = sqlTokens(code);
  const declared = new Set();
  const skip = new Set();
  const symbols = [];
  const refs = [];

  // Pass 1: each `create` names one object; an index or trigger also reads the table after its `on`.
  for (let i = 0; i < toks.length; i++) {
    if (sqlLow(toks[i]) !== 'create') continue;
    let j = i + 1;
    while (toks[j] && toks[j].w && SQL_MODS.has(sqlLow(toks[j]))) j++;
    const kw = sqlLow(toks[j]);
    const kind = SQL_KIND.get(kw);
    if (!kind) continue;
    const k = sqlSkipOptional(toks, j + 1);
    const named = toks[k];
    if (named && named.w && named.v && sqlLow(named) !== 'on') {
      declared.add(k);
      symbols.push({ name: sqlLast(named.v), kind, line: named.line, exported: true });
    }
    if (kw === 'index' || kw === 'trigger') {
      let on = k;
      while (toks[on] && toks[on].v !== ';' && sqlLow(toks[on]) !== 'on') on++;
      const target = sqlSkipOptional(toks, on + 1);
      if (sqlLow(toks[on]) === 'on' && toks[target] && toks[target].w && toks[target].v) {
        refs.push({ at: target, name: sqlLast(toks[target].v), line: toks[target].line });
        skip.add(target);
      }
    }
  }

  // Pass 2: a keyword reads the object after it; any other name followed by `(` is a call unless it is a builtin.
  for (let i = 0; i < toks.length; i++) {
    const t = toks[i];
    if (!t.w || declared.has(i) || skip.has(i)) continue;
    const low = sqlLow(t);
    if (SQL_REF_KW.has(low)) {
      const target = sqlSkipOptional(toks, i + 1);
      const tt = toks[target];
      if (tt && tt.w && tt.v && !declared.has(target) && !skip.has(target) && !SQL_NOT_TARGET.has(sqlLow(tt))) {
        refs.push({ at: target, name: sqlLast(tt.v), line: tt.line });
        skip.add(target);
      }
      continue;
    }
    if (toks[i + 1] && toks[i + 1].v === '(' && !SQL_NOT_CALL.has(low)) refs.push({ at: i, name: sqlLast(t.v), line: t.line });
  }

  // `\i file.sql` and `\ir file.sql` (psql) and `source file.sql` (mysql), one per line.
  const imports = [];
  code.split('\n').forEach((ln, idx) => {
    const psql = /^\s*\\ir?\s+([^\s;]+);?\s*$/.exec(ln);
    const mysql = /^\s*source\s+([^\s;]*[./][^\s;]*);?\s*$/i.exec(ln);
    const m = psql || mysql;
    if (m) imports.push({ spec: m[1], line: idx + 1, names: [] });
  });

  symbols.sort((a, b) => a.line - b.line);
  refs.sort((a, b) => a.at - b.at);
  return { symbols, imports, refs: refs.map(({ name, line }) => ({ name, line })), extends: [] };
}

function sqlIndex(files) {
  let set = SQL_INDEX.get(files);
  if (!set) {
    set = new Set(files);
    SQL_INDEX.set(files, set);
  }
  return set;
}

// Only a path relative to the including file resolves; psql runs the path from the working directory, which is
// not known from the repo, so other forms stay unresolved.
function sqlResolve(spec, fromPath, files) {
  const dir = fromPath.slice(0, fromPath.lastIndexOf('/') + 1);
  const out = [];
  for (const seg of (dir + spec).split('/')) {
    if (seg === '' || seg === '.') continue;
    if (seg === '..') out.pop();
    else out.push(seg);
  }
  const rel = out.join('/');
  return sqlIndex(files).has(rel) ? rel : null;
}

const sqlLang = {
  id: 'sql',
  exts: ['.sql'],
  extract(text) {
    return sqlParse(text);
  },
  resolve: sqlResolve,
};

// ---- server/codemap/lang/swift.js ----
// Swift for the code map. Comments and string literals are blanked first. Swift ends a statement at a
// newline, not at `;`, so declarations are read line by line, and braces are counted across lines to
// know which scope each line is in.

const swTypeKinds = { class: 'class', struct: 'class', enum: 'enum', protocol: 'type', extension: 'type' };

// Words that start a statement or a declaration. None of them is a called name.
const swKeywords = new Set(['if', 'guard', 'while', 'for', 'switch', 'return', 'catch', 'throw', 'in', 'where',
  'else', 'repeat', 'init', 'self', 'super', 'try', 'await', 'as', 'is', 'subscript', 'case', 'func', 'defer']);

// Attributes, modifiers, the keyword, the name. `class func f()` is the modifier `class` on a func.
const swDecl = /^\s*((?:@\w+(?:\([^)]*\))?\s+)*)((?:(?:public|open|internal|private|fileprivate|final|static|class|override|mutating|nonmutating|convenience|required|lazy|dynamic|indirect|weak|unowned)(?:\(set\))?\s+)*)(class|struct|enum|protocol|extension|typealias|func|let|var)\s+([A-Za-z_]\w*)/;
const swImport = /^\s*(?:@\w+\s+)*import\s+(?:(?:class|struct|enum|protocol|typealias|var|let|func)\s+)?([A-Za-z_][\w.]*)\s*$/;
// A name followed by `(`, not after `func` (a declaration) or `case` (an enum case).
const swCall = /(?<!\w)(?<!\b(?:func|case)\s+)([A-Za-z_]\w*)(?:<[\w.,<>[\]?]*>)?\s*\(/g;
const swAttribute = /(?<!\w)@([A-Za-z_]\w*)/g;

function swExtract(text) {
  const code = swStrip(String(text ?? ''));
  const lines = code.split('\n');
  const starts = swLineStarts(code);
  const symbols = [];
  const imports = [];
  const extendsList = [];
  const stack = [];
  // A type whose `{` comes on the next line; the brace line starts with `{`.
  let pending = null;

  for (let index = 0; index < lines.length; index++) {
    const line = lines[index];
    const lineNo = index + 1;
    const top = stack[stack.length - 1];
    const moduleScope = stack.length === 0;
    const classScope = top?.kind === 'type' && top.level === 1;

    if (moduleScope) {
      const imported = swImport.exec(line);
      if (imported) imports.push({ spec: imported[1], line: lineNo, names: [] });
    }

    // The entry the first `{` of this line pushes; a body when null. A type header can run over lines
    // (a where clause on its own line), so its entry waits for the first `{` after it.
    let opening = null;
    if (pending && line.includes('{')) {
      opening = pending;
      pending = null;
    }

    const decl = swDecl.exec(line);
    if (decl) {
      const [, , mods, keyword, name] = decl;
      const exported = !/\b(?:private|fileprivate)\b/.test(mods.replace(/\w+\(set\)/g, ''));
      const isFunc = keyword === 'func';
      // `func` needs its parameter list on the same line; without one it is not a declaration.
      const callable = !isFunc || /^\s*[(<]/.test(line.slice(decl[0].length));
      if (swTypeKinds[keyword]) {
        const level = moduleScope ? 1 : classScope ? 2 : 3;
        const qual = level === 1 ? name : level === 2 ? `${top.qual}.${name}` : null;
        if (level < 3) {
          symbols.push({ name: qual, kind: swTypeKinds[keyword], line: lineNo, exported });
          // An enum's colon names its raw type, not a base.
          if (keyword !== 'enum') {
            for (const base of swBases(line.slice(decl[0].length))) {
              extendsList.push({ name: qual, base, line: lineNo });
            }
          }
        }
        const entry = { kind: 'type', level, qual };
        if (line.includes('{')) opening = entry;
        else pending = entry;
      } else if (keyword === 'typealias') {
        if (moduleScope) symbols.push({ name, kind: 'type', line: lineNo, exported });
      } else if (isFunc && callable) {
        if (moduleScope) symbols.push({ name, kind: 'fn', line: lineNo, exported });
        else if (classScope) symbols.push({ name: `${top.qual}.${name}`, kind: 'method', line: lineNo, exported });
      } else if (moduleScope && (keyword === 'let' || keyword === 'var')) {
        symbols.push({ name, kind: keyword === 'let' ? 'const' : 'var', line: lineNo, exported });
      }
    }

    for (const ch of line) {
      if (ch === '{') {
        stack.push(opening ?? { kind: 'body' });
        opening = null;
      } else if (ch === '}') {
        stack.pop();
      }
    }
  }

  const found = [];
  for (const call of code.matchAll(swCall)) {
    if (!swKeywords.has(call[1])) found.push({ name: call[1], at: call.index });
  }
  for (const attr of code.matchAll(swAttribute)) found.push({ name: attr[1], at: attr.index });
  found.sort((a, b) => a.at - b.at);
  const seen = new Set();
  const refs = [];
  for (const { name, at } of found) {
    const line = swLineOf(starts, at);
    if (seen.has(`${line} ${name}`)) continue;
    seen.add(`${line} ${name}`);
    refs.push({ name, line });
  }

  return { symbols, imports, refs, extends: extendsList };
}

// Base types after the first colon of a declaration. Generic arguments go first, so a constraint's
// colon inside `<T: Equatable>` is not taken; a `where` clause is cut off before the colon is searched.
function swBases(tail) {
  let text = tail.split('{')[0].split(/\bwhere\b/)[0];
  while (/<[^<>]*>/.test(text)) text = text.replace(/<[^<>]*>/g, '');
  const colon = text.indexOf(':');
  if (colon < 0) return [];
  return text
    .slice(colon + 1)
    .split(',')
    .map((item) => /([A-Za-z_]\w*)\s*$/.exec(item.trim())?.[1])
    .filter(Boolean);
}

function swLineStarts(text) {
  const starts = [0];
  for (let i = text.indexOf('\n'); i >= 0; i = text.indexOf('\n', i + 1)) starts.push(i + 1);
  return starts;
}

function swLineOf(starts, pos) {
  let lo = 0;
  let hi = starts.length - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (starts[mid] <= pos) lo = mid;
    else hi = mid - 1;
  }
  return lo + 1;
}

// Comments (nested `/* */` too) become spaces and string literals become `""`, keeping every newline.
function swStrip(text) {
  let out = '';
  let i = 0;
  while (i < text.length) {
    const c = text[i];
    if (c === '/' && text[i + 1] === '/') {
      const end = text.indexOf('\n', i);
      const stop = end < 0 ? text.length : end;
      out += ' '.repeat(stop - i);
      i = stop;
    } else if (c === '/' && text[i + 1] === '*') {
      let depth = 0;
      let j = i;
      while (j < text.length) {
        if (text[j] === '/' && text[j + 1] === '*') {
          depth++;
          j += 2;
        } else if (text[j] === '*' && text[j + 1] === '/') {
          depth--;
          j += 2;
          if (depth === 0) break;
        } else {
          j++;
        }
      }
      out += text.slice(i, j).replace(/[^\n]/g, ' ');
      i = j;
    } else if (c === '"') {
      const end = swStringEnd(text, i);
      out += `""${text.slice(i, end).replace(/[^\n]/g, '')}`;
      i = end;
    } else {
      out += c;
      i++;
    }
  }
  return out;
}

// The index just past the string literal at `start`. An interpolation `\( ... )` is skipped whole,
// so a string inside it does not end the literal early. A single-line string stops at its line end.
function swStringEnd(text, start) {
  const multi = text.startsWith('"""', start);
  let j = start + (multi ? 3 : 1);
  while (j < text.length) {
    const c = text[j];
    if (c === '\\') {
      j = text[j + 1] === '(' ? swInterpolationEnd(text, j + 2) : j + 2;
      continue;
    }
    if (multi && text.startsWith('"""', j)) return j + 3;
    if (!multi && c === '"') return j + 1;
    if (!multi && c === '\n') return j;
    j++;
  }
  return text.length;
}

function swInterpolationEnd(text, j) {
  let depth = 1;
  while (j < text.length) {
    const c = text[j];
    if (c === '"') {
      j = swStringEnd(text, j);
      continue;
    }
    if (c === '(') depth++;
    else if (c === ')') {
      depth--;
      if (depth === 0) return j + 1;
    }
    j++;
  }
  return text.length;
}

// Swift imports name modules, not files. A module's sources live under a directory with its name
// (Sources/<Module>/), so the first Swift file with such a directory on its path is the one taken.
// For `import struct Mod.Name` the first segment names the module; fromPath is not used.
function swResolve(spec, fromPath, files) {
  const moduleName = spec.split('.')[0];
  if (!moduleName) return null;
  for (const file of files) {
    if (!file.endsWith('.swift')) continue;
    const directories = file.split('/').slice(0, -1);
    if (directories.includes(moduleName)) return file;
  }
  return null;
}

const swiftLang = {
  id: 'swift',
  exts: ['.swift'],
  extract: swExtract,
  resolve: swResolve,
};

// ---- server/codemap/lang/index.js ----
// The languages the code map reads, and which one a file is in.

const LANGS = [jsLang, markdownLang, htmlLang, pythonLang, goLang, rustLang, javaLang, kotlinLang, csharpLang, swiftLang, rubyLang, phpLang, cLang, sqlLang];

// by extension, then by a special file name (a Makefile has no extension)
function langFor(path) {
  const base = path.slice(path.lastIndexOf('/') + 1), dot = base.lastIndexOf('.');
  const ext = dot > 0 ? base.slice(dot).toLowerCase() : '';
  return (ext && LANGS.find((l) => l.exts.includes(ext))) || LANGS.find((l) => l.names && l.names.includes(base)) || null;
}

// ---- server/codemap/graph.js ----
// Reading a code map: a node and its connections, a file's outline, the path between two names, a search, what
// depends on a change, where open tasks touch the same code, and the slice of the map a task needs. Imports nothing
// and uses no Node API: the board page carries a copy of this file, so the page and the tools answer alike.

// a file defining many functions, or a doc with many sections, is not thereby central
const GRAPH_STRUCTURE = { defines: 1, contains: 1 };
const GRAPH_GROUPS = [['defines', 'out', 'defines'], ['sections', 'out', 'contains'], ['imports', 'out', 'imports'],
  ['imported by', 'in', 'imports'], ['calls', 'out', 'calls'], ['called by', 'in', 'calls'], ['uses', 'out', 'uses'],
  ['used by', 'in', 'uses'], ['extends', 'out', 'extends'],
  ['extended by', 'in', 'extends'], ['mentions', 'out', 'mentions'], ['mentioned in', 'in', 'mentions']];
const GRAPH_DEPENDS = { imports: 1, calls: 1, uses: 1, extends: 1 };
const GRAPH_CODE = { imports: 1, calls: 1, uses: 1, extends: 1, defines: 1 };
const GRAPH_SEEDS = 6;
// a word matching more nodes than this, and this many times the nodes the question's rarest word matches, is common;
// docs show this many lines
const GRAPH_COMMON_MIN = 5, GRAPH_COMMON_RATIO = 4, GRAPH_DOC_LINES = 4;
const GRAPH_STOP = new Set(['the', 'and', 'for', 'with', 'that', 'this', 'from', 'into', 'when', 'what', 'where', 'which',
  'how', 'why', 'are', 'was', 'were', 'has', 'have', 'had', 'not', 'but', 'all', 'any', 'can', 'does', 'did', 'its', 'our',
  'out', 'use', 'using', 'used', 'should', 'would', 'could', 'will', 'then', 'than', 'them', 'they', 'there', 'their',
  'about', 'after', 'before', 'over', 'under', 'also', 'each', 'every', 'only', 'just', 'more', 'most', 'some', 'such',
  'very', 'been', 'being', 'both', 'same', 'other', 'make', 'need', 'needs', 'want', 'code', 'file', 'files', 'add', 'fix',
  'new', 'way', 'work', 'works', 'like', 'see', 'get', 'got', 'who', 'you', 'your']);

const graphCmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const graphPush = (map, key, v) => { const list = map.get(key); if (list) list.push(v); else map.set(key, [v]); };
const graphKind = (n) => (n.k === 'sym' || n.k === 'sec' ? n.t || n.k : n.k);
const graphWhere = (n) => (n.l ? `${n.f}:${n.l}` : n.f);
// a symbol's declaration after its line, shortened for list lines
const graphSig = (n, max = 80) => (n.s ? ` · ${n.s.length > max ? `${n.s.slice(0, max - 1)}…` : n.s}` : '');
const graphDeg = (g, id) => g.degree.get(id) || 0;
const graphByDegree = (g) => (a, b) => graphDeg(g, b) - graphDeg(g, a) || graphCmp(a, b);
const graphByLine = (g) => (a, b) => (g.nodes.get(a).l || 0) - (g.nodes.get(b).l || 0) || graphCmp(a, b);
// a function declared inside another ('makeFlow.post') is a function by its own name ('post'); a method is not
const graphShort = (n) => (n.k === 'sym' && n.t === 'fn' && n.n.includes('.') ? n.n.slice(n.n.lastIndexOf('.') + 1) : n.n);

// edges per node, both directions, leaving out a file's own definitions and a doc's own sections
function mapDegrees(edges) {
  const deg = new Map();
  for (const [from, to, type] of edges) {
    if (GRAPH_STRUCTURE[type]) continue;
    deg.set(from, (deg.get(from) || 0) + 1);
    deg.set(to, (deg.get(to) || 0) + 1);
  }
  return deg;
}

// Up to limit items as lines, then how many were left out; with more, also the limit that shows them all (rounded
// up to ten), since an agent that is not told does not ask.
function graphList(lines, items, limit, line, more) {
  for (const it of items.slice(0, limit)) lines.push(line(it));
  if (items.length > limit) lines.push(`  … ${items.length - limit} more${more ? ` (limit ${Math.ceil(items.length / 10) * 10})` : ''}`);
}

function graphCommunity(g, n) {
  const c = n && n.c != null && (g.index.communities || []).find((x) => x.c === n.c);
  return c ? c.name : '';
}

// The nodes a name may mean, most exact first: an id, a name as written (a nested function's own name too), a name in
// any case, a method by its last part, the end of a file path. A tie between code and doc sections goes to the code.
function graphFind(g, q) {
  const s = String(q == null ? '' : q).trim().replace(/^\.\//, '');
  if (!s) return [];
  if (g.nodes.has(s)) return [s];
  const lower = s.toLowerCase(), named = g.names.get(lower) || [], lasts = g.lasts.get(lower) || [];
  const tiers = [
    named.filter((id) => g.nodes.get(id).n === s || graphShort(g.nodes.get(id)) === s),
    named,
    lasts.filter((id) => g.nodes.get(id).n.endsWith(`.${s}`)),
    lasts,
    s.includes('/') ? g.ids.filter((id) => { const k = g.nodes.get(id).k; return (k === 'file' || k === 'doc') && id.endsWith(`/${s}`); }) : [],
  ];
  for (const t of tiers) {
    if (!t.length) continue;
    const code = t.filter((id) => g.nodes.get(id).k !== 'sec');
    return code.length ? code : t;
  }
  return [];
}

// one node for a name, or the answer that says why not
function graphOne(g, q) {
  const ids = graphFind(g, q);
  if (ids.length === 1) return { id: ids[0] };
  if (!ids.length) return { lines: [`not in the map: ${q}`], missing: true };
  const lines = [`${q} names ${ids.length}; say which:`];
  graphList(lines, ids, 12, (id) => `  ${id} · ${graphKind(g.nodes.get(id))} · ${graphWhere(g.nodes.get(id))}`);
  return { lines, ambiguous: ids };
}

function graphHead(g, n) {
  const c = graphCommunity(g, n);
  return `${n.n} · ${graphKind(n)} · ${graphWhere(n)}${c ? ` · community ${c}` : ''} · degree ${graphDeg(g, n.i)}`;
}

function graphExplain(g, name, { limit = 30 } = {}) {
  const hit = graphOne(g, name);
  if (!hit.id) return hit;
  const n = g.nodes.get(hit.id), lines = [graphHead(g, n)];
  // what it takes and what it is for, so the answer needs no trip to the file
  if (n.s) lines.push(n.s);
  if (n.d) lines.push(`// ${n.d}`);
  for (const [label, dir, type] of GRAPH_GROUPS) {
    const other = (e) => (dir === 'out' ? e.to : e.from);
    const order = GRAPH_STRUCTURE[type] ? graphByLine(g) : graphByDegree(g);
    const es = (g[dir].get(n.i) || []).filter((e) => e.type === type).sort((a, b) => order(other(a), other(b)));
    if (!es.length) continue;
    lines.push(`${label}:`);
    graphList(lines, es, limit, (e) => `  ${other(e)} [${e.conf}]`, true);
  }
  return { lines, id: n.i };
}

// the other ends of edges of one type into or out of any of ids, each once with its surest conf, sorted by id
function graphEnds(g, ids, dir, type) {
  const ends = new Map(), own = new Set(ids);
  for (const id of ids) {
    for (const e of g[dir].get(id) || []) {
      const end = dir === 'out' ? e.to : e.from;
      if (e.type !== type || own.has(end)) continue;
      if (!ends.has(end) || e.conf === 'x') ends.set(end, e.conf);
    }
  }
  return [...ends].sort((a, b) => graphCmp(a[0], b[0]));
}

function graphFile(g, path, { limit = 30 } = {}) {
  const files = [...new Set(graphFind(g, path).map((id) => g.nodes.get(id).f))].filter((f) => g.nodes.has(f));
  if (files.length !== 1) return files.length ? graphOne(g, path) : { lines: [`not in the map: ${path}`], missing: true };
  const f = g.nodes.get(files[0]), all = g.files.get(f.i) || [f.i];
  const inner = all.filter((id) => id !== f.i).sort(graphByLine(g));
  const importers = graphEnds(g, [f.i], 'in', 'imports'), c = graphCommunity(g, f);
  const what = f.k === 'doc' ? 'sections' : 'symbols';
  const lines = [`${f.i} · ${f.k}${c ? ` · community ${c}` : ''} · ${inner.length} ${what} · imported by ${importers.length}`];
  if (inner.length) {
    lines.push(`${what}:`);
    graphList(lines, inner, limit, (id) => { const n = g.nodes.get(id); return `  ${n.n} ${graphKind(n)} ${n.l}${graphSig(n)}`; }, true);
  }
  const groups = [['imports', graphEnds(g, [f.i], 'out', 'imports')], ['imported by', importers],
    ['mentions', graphEnds(g, all, 'out', 'mentions')], ['mentioned in', graphEnds(g, all, 'in', 'mentions')]];
  for (const [label, ends] of groups) {
    if (!ends.length) continue;
    lines.push(`${label}:`);
    graphList(lines, ends, limit, ([id, conf]) => `  ${id} [${conf}]`, true);
  }
  return { lines, id: f.i, symbols: inner };
}

// breadth first over the edges keep accepts, either way along each; how each reached node was reached, or null
function graphWalk(g, from, to, max, keep) {
  const prev = new Map([[from, null]]);
  let frontier = [from];
  for (let d = 0; d < max && frontier.length && !prev.has(to); d++) {
    const next = [];
    for (const id of frontier) {
      const steps = (g.out.get(id) || []).filter(keep).map((e) => [e.to, e])
        .concat((g.in.get(id) || []).filter(keep).map((e) => [e.from, e])).sort((x, y) => graphCmp(x[0], y[0]));
      for (const [n, e] of steps) if (!prev.has(n)) { prev.set(n, [id, e]); next.push(n); }
    }
    frontier = next;
  }
  return prev.has(to) ? prev : null;
}

// the shortest chain of edges between two names, whichever way each edge points; through code alone when there is
// one, since a doc that mentions both says little about how they connect
function graphPath(g, a, b, { max = 6 } = {}) {
  const A = graphOne(g, a);
  if (!A.id) return A;
  const B = graphOne(g, b);
  if (!B.id) return B;
  const prev = graphWalk(g, A.id, B.id, max, (e) => GRAPH_CODE[e.type]) || graphWalk(g, A.id, B.id, max, () => true);
  if (!prev) return { lines: [`no path from ${A.id} to ${B.id} within ${max} steps`], missing: true };
  const steps = [];
  for (let id = B.id; prev.get(id); id = prev.get(id)[0]) steps.unshift({ at: prev.get(id)[0], to: id, e: prev.get(id)[1] });
  const line = steps.reduce((s, { at, to, e }) => `${s}${e.from === at ? ` --${e.type}--> ` : ` <--${e.type}-- `}${to}`, A.id);
  const guessed = steps.filter((s) => s.e.conf === 'i').map((s) => `${s.e.from} → ${s.e.to}`);
  return { lines: guessed.length ? [line, `matched by name: ${guessed.join(', ')}`] : [line], path: [A.id, ...steps.map((s) => s.to)] };
}

// what a word can match on a node: its names (×3), the parts of its path or name (×2), and its text (×1)
function graphTerms(g) {
  if (g.terms) return g.terms;
  g.terms = new Map();
  for (const id of g.ids) {
    const n = g.nodes.get(id), name = String(n.n || '');
    let names, parts, hay;
    if (n.k === 'file' || n.k === 'doc') {
      names = [name.replace(/\.[^.]+$/, '').toLowerCase()];
      parts = id.toLowerCase().split(/[/._-]+/);
      hay = id.toLowerCase();
    } else if (n.k === 'sym') {
      const last = name.slice(name.lastIndexOf('.') + 1);
      names = [name.toLowerCase(), last.toLowerCase()];
      parts = last.replace(/([a-z0-9])([A-Z])/g, '$1 $2').toLowerCase().split(/[\s_$]+/);
      hay = name.toLowerCase();
    } else {
      names = [name.toLowerCase()];
      parts = name.toLowerCase().split(/[^\p{L}\p{N}_]+/u);
      hay = names[0];
    }
    g.terms.set(id, { names, parts, hay });
  }
  return g.terms;
}

// how well a word matches a node: one of its names 3, a part of its path or name 2, somewhere in its text 1
const graphMatch = (t, w) => (t.names.includes(w) ? 3 : t.parts.includes(w) ? 2 : t.hay.includes(w) ? 1 : 0);

function graphQuery(g, text, { limit = 20 } = {}) {
  const words = [...new Set(String(text || '').toLowerCase().split(/[^\p{L}\p{N}_]+/u))].filter((w) => w.length >= 3 && !GRAPH_STOP.has(w));
  const terms = graphTerms(g), hits = words.map(() => []);
  for (const id of g.ids) words.forEach((w, k) => { const m = graphMatch(terms.get(id), w); if (m) hits[k].push([id, m]); });
  // A word counts less the more nodes it matches. A common word ('read' is in every reader and every README) cannot
  // carry a node alone when the question has a rarer word: such a node must match one of those.
  const rarest = Math.min(...hits.map((list) => list.length || Infinity));
  const common = hits.map((list) => list.length > GRAPH_COMMON_MIN && list.length >= GRAPH_COMMON_RATIO * rarest);
  const rare = hits.some((list, k) => list.length && !common[k]);
  const score = new Map(), carried = new Set();
  hits.forEach((list, k) => {
    for (const [id, m] of list) {
      score.set(id, (score.get(id) || 0) + m / Math.log(2 + list.length));
      if (!common[k]) carried.add(id);
    }
  });
  for (const id of [...score.keys()]) {
    if (rare && !carried.has(id)) score.delete(id);
    else score.set(id, score.get(id) * Math.log(2 + graphDeg(g, id)));
  }
  if (!score.size) return { lines: [`nothing in the map matches: ${text}`], missing: true };
  const byScore = (a, b) => score.get(b) - score.get(a) || graphCmp(a, b);
  // the best matches bring their neighbors: a matching function brings its file, its callers and what it calls
  for (const seed of [...score.keys()].sort(byScore).slice(0, GRAPH_SEEDS)) {
    const near = score.get(seed) / 4;
    for (const e of (g.out.get(seed) || []).concat(g.in.get(seed) || [])) {
      const other = e.from === seed ? e.to : e.from;
      if ((score.get(other) || 0) < near) score.set(other, near);
    }
  }
  // code first and tests after the code they test; docs apart, a few
  const isCode = (id) => g.nodes.get(id).k === 'file' || g.nodes.get(id).k === 'sym';
  const isTest = (id) => { const f = g.nodes.get(g.nodes.get(id).f); return f && f.q === 't' ? 1 : 0; };
  const code = [...score.keys()].filter(isCode).sort((a, b) => isTest(a) - isTest(b) || byScore(a, b)).slice(0, limit);
  const kinds = { files: code.filter((id) => g.nodes.get(id).k === 'file'), symbols: code.filter((id) => g.nodes.get(id).k === 'sym'),
    docs: [...score.keys()].filter((id) => !isCode(id)).sort(byScore).slice(0, GRAPH_DOC_LINES) };
  const symbolCount = (id) => (g.files.get(id) || []).filter((s) => g.nodes.get(s).k === 'sym').length;
  const show = {
    files: (id) => { const c = graphCommunity(g, g.nodes.get(id)); return `  ${id} · ${symbolCount(id)} symbols${c ? ` · ${c}` : ''}`; },
    symbols: (id) => { const n = g.nodes.get(id); return `  ${id} · ${graphKind(n)} · ${n.l}${graphSig(n)}`; },
    docs: (id) => { const n = g.nodes.get(id); return n.k === 'doc' ? `  ${id} · doc` : `  ${id} · ${graphKind(n)} · ${n.l}`; },
  };
  const lines = [];
  for (const k of ['files', 'symbols', 'docs']) {
    if (!kinds[k].length) continue;
    lines.push(`${k}:`);
    for (const id of kinds[k]) lines.push(show[k](id));
  }
  return { lines, ...kinds };
}

// who depends on a node: importers, callers, users and subclasses; for a file, also those of its symbols, from elsewhere
function graphDependents(g, id) {
  const n = g.nodes.get(id), found = [];
  const targets = n.k === 'file' ? g.files.get(id) || [id] : [id];
  for (const t of targets) for (const e of g.in.get(t) || []) if (GRAPH_DEPENDS[e.type]) found.push(e);
  return n.k === 'file' ? found.filter((e) => g.nodes.get(e.from).f !== id) : found;
}

// Breadth first from a node through the edges step gives, to depth; each node once, at its first depth, with the
// edge that reached it (end says which end of an edge is the node reached). A file's own symbols start with it, so
// they are not listed. Prints like impact and inside do, depth by depth.
function graphReach(g, nameOrPath, { depth = 2, limit = 30 } = {}, step, end, head, none) {
  const hit = graphOne(g, nameOrPath);
  if (!hit.id) return hit;
  const start = g.nodes.get(hit.id).k === 'file' ? g.files.get(hit.id) || [hit.id] : [hit.id];
  const seen = new Set(start), levels = [];
  let frontier = start;
  for (let d = 1; d <= depth && frontier.length; d++) {
    const level = [];
    for (const id of frontier) for (const e of step(id)) if (!seen.has(end(e))) { seen.add(end(e)); level.push(e); }
    level.sort((a, b) => graphCmp(end(a), end(b)));
    if (level.length) levels.push(level);
    frontier = level.map(end);
  }
  const total = levels.reduce((s, l) => s + l.length, 0);
  if (!total) return { lines: [none(hit.id)], levels: [] };
  const lines = [head(hit.id, total, depth)];
  levels.forEach((level, d) => {
    lines.push(`depth ${d + 1}:`);
    graphList(lines, level, limit, (e) => `  ${end(e)} [${e.conf}] ${e.type}`, true);
  });
  return { lines, levels: levels.map((l) => l.map(end)) };
}

// what breaks if it changes: who imports, calls, uses or extends it, and theirs
function graphImpact(g, nameOrPath, opts = {}) {
  return graphReach(g, nameOrPath, opts, (id) => graphDependents(g, id), (e) => e.from, (id, n, d) => `impact of ${id}: ${n} dependents within ${d} steps`, (id) => `nothing depends on ${id}`);
}

// what it is made of: what it calls, uses and extends, and theirs (a file: what its symbols do)
function graphInside(g, nameOrPath, opts = {}) {
  const step = (id) => (g.out.get(id) || []).filter((e) => e.type === 'calls' || e.type === 'uses' || e.type === 'extends');
  return graphReach(g, nameOrPath, opts, step, (e) => e.to, (id, n, d) => `inside ${id}: ${n} callees within ${d} steps`,
    (id) => `${id} calls and uses nothing in the map`);
}

function graphOverview(g, { limit = 10 } = {}) {
  const ix = g.index, c = ix.counts || {};
  const built = [ix.builtAt ? `built ${String(ix.builtAt).slice(5, 10)}` : '', ix.by ? `by ${ix.by}` : ''].filter(Boolean).join(' ');
  const lines = [[ix.repo || 'code map', `${c.files || 0} files`, `${c.symbols || 0} symbols`, `${c.edges || 0} edges`,
    `${c.docs || 0} docs`, built].filter(Boolean).join(' · ')];
  const langs = Object.entries(ix.langs || {}).sort((a, b) => b[1] - a[1] || graphCmp(a[0], b[0]));
  if (langs.length) lines.push(`langs: ${langs.map(([l, n]) => `${l} ${n}`).join(' · ')}`);
  const communities = ix.communities || [], god = ix.god || [];
  if (communities.length) {
    lines.push('communities:');
    graphList(lines, communities, limit, (x) => `  ${x.name} · ${x.n} files · ${(x.top || []).slice(0, 3).join(', ')}`);
  }
  if (god.length) {
    lines.push('most connected:');
    graphList(lines, god, limit, (id) => {
      const n = g.nodes.get(id);
      return n ? `  ${id} · ${graphKind(n)} · degree ${graphDeg(g, id)}` : `  ${id}`;
    });
  }
  return { lines, communities, god };
}

// the files a task's touches name: a path, a symbol's file, or the one node a bare name means
function graphTouchFiles(g, touches) {
  const files = new Set();
  for (const t of touches) {
    const ids = graphFind(g, t);
    if (ids.length === 1) files.add(g.nodes.get(ids[0]).f);
  }
  return [...files].filter((f) => g.nodes.has(f));
}

const graphImports = (g, a, b) => (g.out.get(a) || []).some((e) => e.type === 'imports' && e.to === b);

// Open tasks that touch the same code: the same touch written on both; else, with a map, the same file under
// different names, or a file of one importing a file of the other.
function graphOverlaps(g, tasks) {
  const list = (Array.isArray(tasks) ? tasks : []).filter((t) => t && Array.isArray(t.touches) && t.touches.length);
  const who = (t) => (t.holder ? `${t.key} (${t.holder})` : `${t.key}`);
  const lines = [], pairs = [];
  for (let i = 0; i < list.length; i++) {
    for (let j = i + 1; j < list.length; j++) {
      const a = list[i], b = list[j];
      const shared = [...new Set(a.touches.filter((x) => b.touches.includes(x)))];
      let what = shared, hops = [];
      if (!shared.length) {
        const fa = graphTouchFiles(g, a.touches), fb = graphTouchFiles(g, b.touches);
        what = fa.filter((f) => fb.includes(f));
        if (!what.length) {
          for (const x of fa) for (const y of fb) {
            if (graphImports(g, x, y)) hops.push([x, y]);
            else if (graphImports(g, y, x)) hops.push([y, x]);
          }
        }
      }
      if (!what.length && !hops.length) continue;
      lines.push(`${who(a)} ↔ ${who(b)}: ${what.length ? what.join(', ') : hops.map(([x, y]) => `${x} → ${y}`).join(', ')}`);
      pairs.push({ a: a.key, b: b.key, ...(what.length ? { shared: what } : { imports: hops }) });
    }
  }
  return { lines, pairs };
}

// The part of the map a task needs when it is claimed: its touches, the repo paths its text names, and the symbols
// it names in backticks or CamelCase, each as its file with what that file is.
function graphContext(g, task, { limit = 8 } = {}) {
  const t = task || {}, found = new Map();
  const add = (file, name) => {
    if (!g.nodes.has(file)) return;
    if (!found.has(file)) found.set(file, new Set());
    if (name) found.get(file).add(name);
  };
  for (const touch of Array.isArray(t.touches) ? t.touches : []) {
    const ids = graphFind(g, touch);
    if (ids.length === 1) { const n = g.nodes.get(ids[0]); add(n.f, n.k === 'sym' ? n.n : ''); }
  }
  const text = [t.title, t.spec, t.acceptance].filter((s) => typeof s === 'string').join('\n');
  for (const m of text.matchAll(/[\w@~.-]+(?:\/[\w@~.-]+)+|[\w@~-][\w@~.-]*\.[A-Za-z0-9]+/g)) {
    const p = m[0].replace(/^\.\//, '').replace(/[.,;:]+$/, '');
    const n = g.nodes.get(p);
    if (n && (n.k === 'file' || n.k === 'doc')) { add(p, ''); continue; }
    const ends = p.includes('/') ? g.ids.filter((id) => { const k = g.nodes.get(id).k; return (k === 'file' || k === 'doc') && id.endsWith(`/${p}`); }) : [];
    if (ends.length === 1) add(ends[0], '');
  }
  const names = new Set();
  for (const m of text.matchAll(/`([^`\n]+)`/g)) names.add(m[1].trim().replace(/\(.*\)$/, ''));
  for (const m of text.matchAll(/\b[A-Za-z_$][\w$]*[a-z0-9][A-Z][\w$]*/g)) names.add(m[0]);
  for (const name of names) {
    const ids = (g.names.get(name.toLowerCase()) || []).filter((id) => g.nodes.get(id).k === 'sym' && g.nodes.get(id).n === name);
    // a name defined in many places says little about where the work is
    if (ids.length && ids.length <= 3) for (const id of ids) add(g.nodes.get(id).f, name);
  }
  const lines = [];
  for (const [file, syms] of [...found].slice(0, limit)) {
    const n = g.nodes.get(file), c = graphCommunity(g, n);
    const count = (g.files.get(file) || []).filter((id) => g.nodes.get(id).k === 'sym').length;
    const importers = graphEnds(g, [file], 'in', 'imports').length;
    lines.push([file, `${count} symbols`, `imported by ${importers}`, c, [...syms].join(', ')].filter(Boolean).join(' · '));
  }
  return { lines, files: [...found.keys()].slice(0, limit) };
}

function loadGraph(index, chunks) {
  const g = { index: index || {}, nodes: new Map(), out: new Map(), in: new Map(), names: new Map(), lasts: new Map(),
    files: new Map(), ids: [], degree: new Map(), terms: null };
  const edges = [];
  for (const ch of chunks || []) {
    for (const n of (ch && ch.nodes) || []) if (n && typeof n.i === 'string') g.nodes.set(n.i, n);
    for (const e of (ch && ch.edges) || []) if (Array.isArray(e)) edges.push(e);
  }
  const kept = edges.filter(([from, to]) => g.nodes.has(from) && g.nodes.has(to));
  for (const [from, to, type, conf] of kept) {
    const e = { from, to, type, conf };
    graphPush(g.out, from, e);
    graphPush(g.in, to, e);
  }
  g.degree = mapDegrees(kept);
  g.ids = [...g.nodes.keys()].sort(graphCmp);
  for (const id of g.ids) {
    const n = g.nodes.get(id), name = String(n.n || '');
    graphPush(g.names, name.toLowerCase(), id);
    if (graphShort(n) !== name) graphPush(g.names, graphShort(n).toLowerCase(), id);
    if (n.k === 'sym' && name.includes('.')) graphPush(g.lasts, name.slice(name.lastIndexOf('.') + 1).toLowerCase(), id);
    if (n.f) graphPush(g.files, n.f, id);
  }
  return {
    index: g.index,
    explain: (name, opts) => graphExplain(g, name, opts || {}),
    file: (path, opts) => graphFile(g, path, opts || {}),
    path: (a, b, opts) => graphPath(g, a, b, opts || {}),
    query: (text, opts) => graphQuery(g, text, opts || {}),
    impact: (nameOrPath, opts) => graphImpact(g, nameOrPath, opts || {}),
    inside: (nameOrPath, opts) => graphInside(g, nameOrPath, opts || {}),
    overview: (opts) => graphOverview(g, opts || {}),
    overlaps: (tasks) => graphOverlaps(g, tasks),
    context: (task, opts) => graphContext(g, task, opts || {}),
  };
}

// ---- server/codemap/scan.js ----
// The code map's only contact with the file system: which files a checkout has, their text, and its commit.
// Git's own listing is used when there is one, so .gitignore decides what is left out.

const scanExec = promisify(execFile);

// folders that hold installed, built or cached files rather than the project's own code
const SCAN_SKIP_DIRS = new Set(['node_modules', '.git', 'dist', 'build', 'out', 'vendor', 'target', '.venv', '__pycache__', 'coverage']);
const SCAN_LOCKS = new Set(['package-lock.json', 'yarn.lock', 'pnpm-lock.yaml', 'Cargo.lock', 'poetry.lock', 'go.sum']);
const SCAN_MAX_BYTES = 1024 * 1024;
const SCAN_SNIFF_BYTES = 8192;
// generated code says so near its top; its names belong to the files it was made from
const SCAN_GENERATED = /\bgenerated\b|\bdo not edit\b/i;

async function scanGit(root, args) {
  const { stdout } = await scanExec('git', args, { cwd: root, maxBuffer: 256 * 1024 * 1024 });
  return stdout;
}

async function scanWalk(root, dir, out) {
  const entries = await readdir(join(root, dir), { withFileTypes: true }).catch(() => []);
  for (const e of entries) {
    const path = dir ? `${dir}/${e.name}` : e.name;
    // links are not followed: a link to a parent folder would never end
    if (e.isDirectory() && !SCAN_SKIP_DIRS.has(e.name)) await scanWalk(root, path, out);
    else if (e.isFile()) out.push(path);
  }
  return out;
}

const scanNamed = (path) => {
  const parts = path.split('/'), base = parts[parts.length - 1];
  return !parts.slice(0, -1).some((p) => SCAN_SKIP_DIRS.has(p)) && !SCAN_LOCKS.has(base) && !/\.min\.js$/i.test(base);
};

// A regular file of at most 1 MiB, with no NUL byte near its start (binary files carry no names worth mapping) and
// no "generated" or "do not edit" in its first five lines.
async function scanWanted(root, path) {
  try {
    const st = await stat(join(root, path));
    if (!st.isFile() || st.size > SCAN_MAX_BYTES) return false;
    const fh = await open(join(root, path), 'r');
    try {
      const buf = Buffer.alloc(Math.min(SCAN_SNIFF_BYTES, st.size));
      const { bytesRead } = await fh.read(buf, 0, buf.length, 0);
      const head = buf.subarray(0, bytesRead);
      return head.indexOf(0) < 0 && !SCAN_GENERATED.test(head.toString('utf8').split('\n', 5).join('\n'));
    } finally { await fh.close(); }
  } catch { return false; }
}

// many files at once, but not so many that the process runs out of file handles
async function scanEach(items, fn, width = 64) {
  const out = new Array(items.length);
  for (let i = 0; i < items.length; i += width) {
    const part = await Promise.all(items.slice(i, i + width).map(fn));
    for (let j = 0; j < part.length; j++) out[i + j] = part[j];
  }
  return out;
}

// repo-relative paths with '/' separators, sorted
async function listFiles(root) {
  let paths;
  try {
    if ((await scanGit(root, ['rev-parse', '--is-inside-work-tree'])).trim() !== 'true') throw new Error('not a work tree');
    paths = (await scanGit(root, ['ls-files', '-z', '--cached', '--others', '--exclude-standard'])).split('\0').filter(Boolean);
  } catch {
    paths = await scanWalk(root, '', []);
  }
  paths = [...new Set(paths)].filter(scanNamed);
  const keep = await scanEach(paths, (p) => scanWanted(root, p));
  return paths.filter((p, i) => keep[i]).sort();
}

async function readFiles(root, paths) {
  const texts = await scanEach(paths, (p) => readFile(join(root, p), 'utf8').catch(() => null));
  const out = new Map();
  paths.forEach((p, i) => { if (texts[i] != null) out.set(p, texts[i]); });
  return out;
}

// the checked-out commit, or undefined outside a git work tree
async function headCommit(root) {
  try { return (await scanGit(root, ['rev-parse', 'HEAD'])).trim() || undefined; } catch { return undefined; }
}

// ---- server/codemap/build.js ----
// Builds a code map from a checkout's files: nodes for files, symbols and doc sections, the edges between them, and
// communities of files that belong together. No model calls and no clock but builtAt: the same files give the same map.

const BUILD_CHUNK_BYTES = 200000;
const BUILD_COMMUNITIES = 40, BUILD_GOD = 20, BUILD_TOP = 5, BUILD_SMALL = 3;
// names every standard library has: matched by name alone, they are more often a coincidence than a call
const BUILD_COMMON = new Set(['get', 'set', 'has', 'add', 'delete', 'remove', 'clear', 'push', 'pop', 'shift', 'unshift',
  'map', 'filter', 'reduce', 'find', 'forEach', 'some', 'every', 'keys', 'values', 'entries', 'join', 'split', 'slice',
  'splice', 'replace', 'test', 'exec', 'then', 'catch', 'finally', 'log', 'error', 'warn', 'info', 'debug', 'write', 'read',
  'open', 'close', 'start', 'stop', 'run', 'call', 'apply', 'bind', 'toString', 'valueOf', 'sort', 'includes', 'indexOf',
  'concat', 'match', 'trim', 'parse', 'stringify', 'append', 'insert', 'emit', 'send', 'next', 'init', 'main', 'len',
  'print', 'format', 'length', 'size', 'count', 'equals', 'hashCode', 'copy', 'clone', 'reset']);

const buildBase = (p) => p.slice(p.lastIndexOf('/') + 1);
const buildDir = (p) => (p.includes('/') ? p.slice(0, p.lastIndexOf('/')) : '');
const buildTopDir = (p) => (p.includes('/') ? p.slice(0, p.indexOf('/')) : '');
// tests and their fixtures: they follow the code they test, in communities, and stay out of the most connected
const BUILD_TEST_DIRS = new Set(['test', 'tests', '__tests__', 'spec', 'fixtures']);
const buildIsTest = (p) => p.split('/').slice(0, -1).some((d) => BUILD_TEST_DIRS.has(d))
  || /\.(test|spec)\.[^.]+$|_test\.go$|Test\.java$|Tests\.cs$/.test(buildBase(p));
// a heading's id part: lowercase, spaces to '-', only letters, digits and '-' (in any script, so headings that are
// not in English keep their words)
const buildSlug = (s) => s.toLowerCase().replace(/\s+/g, '-').replace(/[^\p{L}\p{N}-]/gu, '');
const buildCmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const buildPush = (map, key, v) => { const list = map.get(key); if (list) list.push(v); else map.set(key, [v]); };

function buildNormalize(p) {
  const out = [];
  for (const part of p.split('/')) {
    if (part === '..') { if (!out.length) return null; out.pop(); }
    else if (part && part !== '.') out.push(part);
  }
  return out.join('/');
}

function buildEdge(b, from, to, type, conf) {
  if (from === to) return;
  const key = `${from}\n${to}\n${type}`, had = b.edges.get(key);
  if (!had || had[3] === 'i' && conf === 'x') b.edges.set(key, [from, to, type, conf]);
}

// the innermost symbol whose lines hold `line`; refs outside every symbol belong to the file
function buildEnclosing(syms, line) {
  let best = null;
  for (const s of syms) {
    if (s.end && s.line <= line && line <= s.end && (!best || s.line > best.line || s.line === best.line && s.end < best.end)) best = s;
  }
  return best;
}

function buildExtract(b, files) {
  for (const p of b.paths) {
    const lang = b.langFor(p);
    if (!lang) continue;
    const text = files.get(p) || '';
    let x;
    // one file a language cannot read costs that file's symbols, not the map
    try { x = lang.extract(text, p) || {}; } catch { x = {}; }
    const lines = text.split('\n');
    b.last.set(p, lines.length - (lines[lines.length - 1] === '' ? 1 : 0));
    b.lines.set(p, lines);
    const list = (v) => (Array.isArray(v) ? v.filter((o) => o && typeof o === 'object') : []);
    b.lang.set(p, lang);
    b.parsed.set(p, { symbols: list(x.symbols), imports: list(x.imports), refs: list(x.refs), extends: list(x.extends) });
    b.nodes.set(p, { i: p, k: lang.doc ? 'doc' : 'file', n: buildBase(p), f: p, l: 0 });
    buildPush(b.stems, lang.id, [p.replace(/\.[^./]+$/, ''), p]);
  }
}

// symbol and section nodes; a name defined twice in one file gets its line appended to the second id
function buildSymbols(b) {
  for (const [p, x] of b.parsed) {
    const doc = !!b.lang.get(p).doc, list = [];
    for (const s of x.symbols) {
      if (typeof s.name !== 'string' || !s.name || !(s.line >= 1)) continue;
      let id = `${p}#${doc ? buildSlug(s.name) : s.name}`;
      if (b.nodes.has(id)) id = `${id}@${s.line}`;
      if (b.nodes.has(id)) continue;
      const node = { i: id, k: doc ? 'sec' : 'sym', n: s.name, f: p, l: s.line, t: s.kind };
      if (!doc && s.exported !== false) node.e = 1;
      if (!doc) {
        const sig = buildSig(b.lines.get(p), s.line, s.kind, b.lang.get(p)), about = buildDoc(b.lines.get(p), s.line);
        if (sig) node.s = sig;
        if (about) node.d = about;
      }
      b.nodes.set(id, node);
      buildEdge(b, p, id, doc ? 'contains' : 'defines', 'x');
      // a function nested in another ('makeFlow.post') is reached through its scope only: `xs.map(` is not makeFlow.map
      const method = !doc && (s.kind === 'method' || s.name.includes('.') && s.kind !== 'fn');
      const sym = { id, file: p, name: s.name, kind: s.kind, line: s.line, end: s.end >= s.line ? s.end : null, method,
        last: s.name.slice(s.name.lastIndexOf('.') + 1), exported: s.exported !== false };
      list.push(sym);
      if (doc) continue;
      buildPush(b.byName, s.name, sym);
      if (method) buildPush(b.byLast, sym.last, sym);
    }
    buildEnds(list, b.last.get(p));
    b.syms.set(p, list);
  }
}

const buildCut = (s, n) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);
// kinds whose declaration is followed by a body, cut off from the signature
const BUILD_BODIES = new Set(['fn', 'class', 'method', 'module']);

// The declaration as written, on one line of at most 120 characters: for a function, class or method its line (and
// the next ones while its brackets are open) up to the body (`{`, `=>`, Python's `:`); for the rest the line itself
// less a trailing `{`, `(`, `[`, `=` or `;`. Strings are kept whole; a line comment ends it.
function buildSig(lines, line, kind, lang) {
  const body = BUILD_BODIES.has(kind), py = lang.id === 'python';
  const hash = py || lang.id === 'ruby', dashes = lang.id === 'sql';
  let out = '', depth = 0, quote = '';
  const done = () => buildCut(out.replace(/\s+/g, ' ').trim().replace(/[\s{([=;,]+$/, ''), 120);
  for (let k = line - 1; k < Math.min(lines.length, line + 7); k++) {
    const raw = lines[k];
    for (let i = 0; i < raw.length; i++) {
      const c = raw[i], spaced = i === 0 || /\s/.test(raw[i - 1]);
      if (quote) {
        out += c;
        if (c === '\\') out += raw[++i] || '';
        else if (c === quote) quote = '';
        continue;
      }
      if (c === '"' || c === "'" || c === '`') { quote = c; out += c; continue; }
      if (spaced && (c === '/' && raw[i + 1] === '/' || hash && c === '#' || dashes && c === '-' && raw[i + 1] === '-')) return done();
      if (c === '(' || c === '[' || c === '{') {
        if (c === '{' && body && !depth) return done();
        depth++;
      } else if (c === ')' || c === ']' || c === '}') depth = Math.max(0, depth - 1);
      else if (body && !depth && (c === '=' && raw[i + 1] === '>' || py && c === ':')) return done();
      out += c;
    }
    if (!body || !depth) break;
    out += ' ';
  }
  return done();
}

// The comment just above a symbol, one line of at most 160 characters: `//`, `#`, `--`, `/* … */` and `/** … */`
// lines (decorators between them and the symbol skipped), markers and leading `*` dropped; else a Python docstring's
// first line below it. None when the line above is blank or code.
function buildDoc(lines, line) {
  const parts = [];
  let k = line - 2;
  while (k >= 0 && /^\s*(@|#\[)/.test(lines[k])) k--;
  for (;;) {
    if (k >= 0 && /\*\/\s*$/.test(lines[k])) {
      let top = k;
      while (top > 0 && !lines[top].includes('/*')) top--;
      if (!/^\s*\/\*/.test(lines[top])) break;
      parts.unshift(...lines.slice(top, k + 1).map((l) => l.replace(/^\s*\/\*+|\*+\/\s*$/g, '').replace(/^\s*\*(?!\/)\s?/, '')));
      k = top - 1;
    } else if (k >= 0 && /^\s*(\/\/|#(\s|#|$)|--(\s|-|$))/.test(lines[k])) {
      parts.unshift(lines[k].replace(/^\s*(\/\/+|#+|--+)/, ''));
      k--;
    } else break;
  }
  let text = parts.join(' ').replace(/\s+/g, ' ').trim();
  if (!text) {
    const m = /^[rRuUbB]?("""|''')(.*)$/.exec((lines[line] || '').trim());
    if (m) text = (m[2] || (lines[line + 1] || '')).replace(/("""|''').*$/, '').trim();
  }
  return buildCut(text, 160);
}

// A language that gives no end: a symbol runs to the line before the next symbol, or to the file's last line. Ending
// a class at its first method instead of its last loses nothing: a line goes to the innermost symbol that holds it.
function buildEnds(list, last) {
  const starts = list.map((s) => s.line).sort((x, y) => x - y);
  for (const s of list) {
    if (s.end) continue;
    const next = starts.find((l) => l > s.line);
    s.end = next ? next - 1 : Math.max(last, s.line);
  }
}

// A module name the language could not place, matched by the end of its path: '@/ui/Button' or 'app.models.user'
// name ui/Button.tsx or app/models/user.py when exactly one file of that language ends so. A one-word bare name
// ('react', 'os') is a package far more often than a repo file, so it is left out.
function buildGuess(b, spec, lang) {
  if (spec.startsWith('.') || /^[a-z][\w+.-]*:/i.test(spec) || /^@(?!\/)/.test(spec)) return null;
  const alias = /^[~#@]\//.test(spec);
  const parts = (spec.includes('/') ? spec.split('/') : spec.split('.')).filter((s) => /^[\w-]+$/.test(s));
  if (parts.length < (alias ? 1 : 2)) return null;
  const tail = parts.join('/');
  const hits = (b.stems.get(lang.id) || []).filter(([stem]) => stem === tail || stem.endsWith(`/${tail}`)
    || stem === `${tail}/index` || stem.endsWith(`/${tail}/index`));
  return hits.length === 1 ? hits[0][1] : null;
}

function buildImports(b) {
  for (const [p, x] of b.parsed) {
    const lang = b.lang.get(p), targets = new Map(), outside = new Set();
    for (const imp of x.imports) {
      if (typeof imp.spec !== 'string' || !imp.spec) continue;
      const names = Array.isArray(imp.names) ? imp.names.filter((n) => typeof n === 'string') : [];
      let to = null, conf = 'x';
      try { to = lang.resolve(imp.spec, p, b.paths); } catch { to = null; }
      if (!to || !b.has.has(to)) { to = buildGuess(b, imp.spec, lang); conf = 'i'; }
      if (!to) { names.forEach((n) => outside.add(n)); continue; }
      if (to === p) continue;
      buildEdge(b, p, to, 'imports', conf);
      if (!targets.has(to)) targets.set(to, { names: new Set(), sure: false });
      const t = targets.get(to);
      t.sure = t.sure || conf === 'x';
      names.forEach((n) => t.names.add(n));
    }
    b.imports.set(p, targets);
    b.outside.set(p, outside);
  }
}

// Each step below says which symbol a name used in file p means: [id, 'x' | 'i'], null when the name is ambiguous
// there (it is dropped), or undefined when the step knows nothing of it and the next one asks.

// 1. this file's own names
function buildInFile(b, p, lang, ref, from) {
  const { name } = ref, own = b.syms.get(p) || [];
  const cls = from && from.method ? from.name.slice(0, from.name.lastIndexOf('.')) : null;
  const mine = cls && own.find((s) => s.name === `${cls}.${name}`);
  if (ref.self && mine) return [mine.id, 'x'];
  if (ref.member) {
    const here = own.filter((s) => s.method && s.last === name);
    return here.length ? (here.length === 1 ? [here[0].id, 'i'] : null) : undefined;
  }
  // a function declared in the function the call is in, or beside it there, is the one the language's scope finds
  const outer = from && from.kind === 'fn' ? from.name.split('.')[0] : null;
  const nested = outer && own.find((s) => s.kind === 'fn' && s.name === `${outer}.${name}`);
  if (nested) return [nested.id, 'x'];
  const here = own.filter((s) => !s.method && s.name === name);
  if (here.length) return [here[0].id, 'x'];
  // a bare call inside a class may be to the class's own method, in languages where `self` goes unwritten
  if (mine && !ref.base && !lang.moduleScope) return [mine.id, 'i'];
  return undefined;
}

// 2. the files p imports: a method for `obj.name(`, a top-level name otherwise, and where files see only each
// other's exports, an exported one. Explicit ('x') when imported by name through imports that were resolved, not
// guessed; `export { x } from './y'` is followed for a name imported by name.
function buildThroughImports(b, p, lang, ref) {
  const { name } = ref, imports = b.imports.get(p) || new Map(), cands = new Map();
  const fits = (s) => (ref.member ? s.method && s.last === name : !s.method && s.name === name) && (s.exported || !lang.moduleScope);
  for (const [file, t] of imports) {
    for (const s of b.syms.get(file) || []) if (fits(s)) cands.set(s.id, cands.get(s.id) || (t.sure && t.names.has(name)));
  }
  let frontier = [...imports].filter(([, t]) => t.names.has(name)).map(([f, t]) => [f, t.sure]);
  const seen = new Set(frontier.map(([f]) => f));
  for (let hop = 0; hop < 3 && !cands.size && frontier.length; hop++) {
    const next = [];
    for (const [f, sure] of frontier) {
      for (const [g, t] of b.imports.get(f) || []) if (t.names.has(name) && !seen.has(g)) { seen.add(g); next.push([g, sure && t.sure]); }
    }
    for (const [g, sure] of next) for (const s of b.syms.get(g) || []) if (fits(s)) cands.set(s.id, sure);
    frontier = next;
  }
  const all = [...cands], sure = all.filter(([, x]) => x);
  if (all.length === 1) return [all[0][0], all[0][1] ? 'x' : 'i'];
  if (sure.length === 1) return [sure[0][0], 'x'];
  return all.length ? null : undefined;
}

// 3. the one symbol of that name in the repo, in the same language, for languages whose files see each other's
// names without an import; never a name p imported from a package, or one every library has
function buildByName(b, p, lang, ref) {
  const { name } = ref;
  if (lang.moduleScope || b.outside.get(p).has(name) || BUILD_COMMON.has(name) || name.length < 3) return null;
  const sameLang = (s) => s.file !== p && b.lang.get(s.file) === lang;
  let pool = ref.member ? [] : (b.byName.get(name) || []).filter((s) => !s.method && sameLang(s));
  if (!pool.length && !ref.base) pool = (b.byLast.get(name) || []).filter(sameLang);
  return pool.length === 1 ? [pool[0].id, 'i'] : null;
}

// a name used as a value (passed, stored, returned): only where it is certain, bound in this file or imported by
// name; a guess would be noise
function buildUse(b, p, lang, ref, from) {
  const hit = buildInFile(b, p, lang, { name: ref.name }, from) ?? buildThroughImports(b, p, lang, { name: ref.name });
  return hit && hit[1] === 'x' ? hit : null;
}

function buildResolve(b, p, lang, ref, from) {
  for (const step of [() => buildInFile(b, p, lang, ref, from), () => buildThroughImports(b, p, lang, ref)]) {
    const hit = step();
    if (hit !== undefined) return hit;
  }
  return buildByName(b, p, lang, ref);
}

// calls, uses and extends; a base named in `extends` is not also a call
function buildRefs(b) {
  for (const [p, x] of b.parsed) {
    const lang = b.lang.get(p);
    if (lang.doc) continue;
    const syms = b.syms.get(p), bases = new Set(x.extends.map((e) => `${e.line} ${e.base}`));
    for (const ref of x.refs) {
      if (typeof ref.name !== 'string' || !ref.name || bases.has(`${ref.line} ${ref.name}`)) continue;
      const from = buildEnclosing(syms, ref.line);
      const hit = ref.use ? buildUse(b, p, lang, ref, from) : buildResolve(b, p, lang, ref, from);
      if (hit) buildEdge(b, from ? from.id : p, hit[0], ref.use ? 'uses' : 'calls', hit[1]);
    }
    for (const e of x.extends) {
      if (typeof e.base !== 'string' || !e.base) continue;
      const own = syms.find((s) => s.name === e.name && !s.method) || null;
      const hit = buildResolve(b, p, lang, { name: e.base, base: true }, own);
      if (hit) buildEdge(b, own ? own.id : p, hit[0], 'extends', hit[1]);
    }
  }
}

// a path written in a doc: from the doc's folder, as its links are, then from the repo root ('x'); else the one file
// whose path ends so ('i')
function buildPathMention(b, doc, written) {
  const p = written.replace(/[#?:].*$/, '').replace(/^\.\//, '');
  const rel = buildNormalize(`${buildDir(doc)}/${p}`);
  if (rel && b.has.has(rel)) return [rel, 'x'];
  if (b.has.has(p)) return [p, 'x'];
  const tail = `/${p.replace(/^(\.\.?\/)+/, '')}`;
  const hits = (b.bases.get(buildBase(p)) || []).filter((f) => `/${f}`.endsWith(tail));
  return hits.length === 1 ? [hits[0], 'i'] : null;
}

// a backticked name in a doc: an id as written ('x'), or the one symbol of that name ('i')
function buildNameMention(b, name) {
  if (name.includes('#')) return b.nodes.get(name)?.k === 'sym' ? [name, 'x'] : null;
  if (BUILD_COMMON.has(name) || name.length < 3) return null;
  const hits = b.byName.get(name) || [];
  return hits.length === 1 ? [hits[0].id, 'i'] : null;
}

function buildMentions(b) {
  for (const [p, x] of b.parsed) {
    if (!b.lang.get(p).doc) continue;
    const secs = b.syms.get(p);
    for (const ref of x.refs) {
      if (typeof ref.name !== 'string' || !ref.name) continue;
      const hit = ref.path ? buildPathMention(b, p, ref.name) : buildNameMention(b, ref.name);
      if (!hit || hit[0] === p) continue;
      const from = buildEnclosing(secs, ref.line);
      buildEdge(b, from ? from.id : p, hit[0], 'mentions', hit[1]);
    }
  }
}

// Label propagation among the files `take` marks, over the links between them only, in sorted order: each takes the
// label its links weigh most for (ties keep the current label, else take the lowest). A link counts less the more
// links its two files have, or a README that names everything would pull the whole repo into one community.
function buildPropagate(adj, label, take) {
  const links = adj.map((m, i) => (take[i] ? [...m].reduce((s, [j, w]) => s + (take[j] ? w : 0), 0) : 0));
  const tie = (x, y) => Math.abs(x - y) < 1e-9;
  take.forEach((t, i) => { if (t) label[i] = i; });
  for (let round = 0; round < 50; round++) {
    let changed = false;
    for (let i = 0; i < adj.length; i++) {
      if (!take[i]) continue;
      const tally = new Map();
      for (const [j, w] of adj[i]) if (take[j]) tally.set(label[j], (tally.get(label[j]) || 0) + w / Math.sqrt(links[i] * links[j]));
      if (!tally.size) continue;
      const max = Math.max(...tally.values());
      const pick = tie(tally.get(label[i]) || 0, max) ? label[i] : Math.min(...[...tally].filter(([, w]) => tie(w, max)).map(([l]) => l));
      if (pick !== label[i]) { label[i] = pick; changed = true; }
    }
    if (!changed) break;
  }
}

// A group's name: the deepest folder at least 60% of its files are in, else the folder most are in when 40% are,
// else its busiest code file. Tests and docs (followers) do not name a group that has other files.
function buildName(members, lead, follows) {
  const own = members.filter((f) => !follows(f));
  const named = own.length ? own : members, held = new Map();
  for (const f of named) {
    const parts = buildDir(f).split('/').filter(Boolean);
    for (let k = 1; k <= parts.length; k++) held.set(parts.slice(0, k).join('/'), (held.get(parts.slice(0, k).join('/')) || 0) + 1);
  }
  const deeper = ([p, n], [q, m]) => m - n || q.split('/').length - p.split('/').length || buildCmp(p, q);
  const most = [...held].sort(deeper)[0];
  const deep = [...held].filter(([, n]) => n * 10 >= named.length * 6).sort(([p], [q]) => q.split('/').length - p.split('/').length)[0];
  if (deep) return deep[0];
  return most && most[1] * 10 >= named.length * 4 ? most[0] : buildBase(lead);
}

// Communities of files over imports and mentions. Code votes among itself; then each test, doc or file of no language
// joins the group whose code it imports or mentions most (a test that imports half the repo, or a README that names
// every folder, would otherwise glue them together), and those that reach no code (a fixture tree) vote among
// themselves. Groups under 3 files join the group they have most links to (code by code links), or a group mostly in
// their top folder. Returns the communities, largest first.
function buildCommunities(b, degree) {
  const files = [...b.nodes.values()].filter((n) => n.k === 'file' || n.k === 'doc').map((n) => n.i).sort(buildCmp);
  const at = new Map(files.map((f, i) => [f, i]));
  const adj = files.map(() => new Map()), outs = files.map(() => new Map());
  for (const [from, to, type] of b.edges.values()) {
    if (type !== 'imports' && type !== 'mentions') continue;
    const x = at.get(b.nodes.get(from).f), y = at.get(b.nodes.get(to).f);
    if (x === y) continue;
    adj[x].set(y, (adj[x].get(y) || 0) + 1);
    adj[y].set(x, (adj[y].get(x) || 0) + 1);
    outs[x].set(y, (outs[x].get(y) || 0) + 1);
  }
  // only code votes: tests, docs and files of no language (package.json, an image) follow what reaches them
  const follows = (f) => buildIsTest(f) || b.nodes.get(f).k === 'doc' || !b.lang.has(f);
  const follower = files.map(follows), label = files.map(() => null);
  buildPropagate(adj, label, follower.map((t) => !t));
  const sizes = new Map();
  label.forEach((l) => { if (l !== null) sizes.set(l, (sizes.get(l) || 0) + 1); });
  follower.forEach((t, i) => {
    if (!t) return;
    const tally = new Map();
    for (const [j, w] of outs[i]) if (!follower[j]) tally.set(label[j], (tally.get(label[j]) || 0) + w);
    let pick = null;
    for (const [l, w] of tally) if (pick === null || w > tally.get(pick) || w === tally.get(pick) && (sizes.get(l) > sizes.get(pick) || sizes.get(l) === sizes.get(pick) && l < pick)) pick = l;
    label[i] = pick;
  });
  buildPropagate(adj, label, label.map((l) => l === null));
  const groups = new Map();
  label.forEach((l, i) => buildPush(groups, l, i));
  const merge = (from, into) => {
    for (const i of groups.get(from)) label[i] = into;
    groups.get(into).push(...groups.get(from));
    groups.delete(from);
  };
  const larger = (t, than) => groups.get(t).length > groups.get(than).length || groups.get(t).length === groups.get(than).length && t < than;
  for (let again = true; again;) {
    again = false;
    for (const l of [...groups.keys()].sort((x, y) => x - y)) {
      const g = groups.get(l);
      if (!g || g.length >= BUILD_SMALL) continue;
      // a group with code in it goes where its code links, not where a doc that names it went
      const code = g.some((i) => !follower[i]), touch = new Map();
      for (const i of g) for (const [j, w] of adj[i]) if (label[j] !== l && (!code || !follower[j])) touch.set(label[j], (touch.get(label[j]) || 0) + w);
      let into = null;
      for (const [t, w] of touch) if (into === null || w > touch.get(into) || w === touch.get(into) && larger(t, into)) into = t;
      if (into !== null) { merge(l, into); again = true; }
    }
  }
  for (const l of [...groups.keys()].sort((x, y) => x - y)) {
    const g = groups.get(l);
    if (!g || g.length >= BUILD_SMALL) continue;
    // a group mostly in that folder, or another small one there: a lone script does not join a group that merely
    // holds one script
    const dir = buildTopDir(files[Math.min(...g)]);
    let into = null, most = 0;
    for (const [t, members] of groups) {
      if (t === l) continue;
      const n = members.filter((i) => buildTopDir(files[i]) === dir).length;
      if (n * 2 < members.length && members.length >= BUILD_SMALL) continue;
      if (n > most || n && n === most && larger(t, into)) { into = t; most = n; }
    }
    if (into !== null) merge(l, into);
  }
  // still alone (code no code reaches, in a folder of its own): where any link goes
  for (const l of [...groups.keys()].sort((x, y) => x - y)) {
    const g = groups.get(l);
    if (!g || g.length >= BUILD_SMALL) continue;
    const touch = new Map();
    for (const i of g) for (const [j, w] of adj[i]) if (label[j] !== l) touch.set(label[j], (touch.get(label[j]) || 0) + w);
    let into = null;
    for (const [t, w] of touch) if (into === null || w > touch.get(into) || w === touch.get(into) && larger(t, into)) into = t;
    if (into !== null) merge(l, into);
  }
  const deg = (id) => degree.get(id) || 0;
  const byDegree = (x, y) => deg(y) - deg(x) || buildCmp(x, y);
  const list = [...groups.values()].map((g) => {
    const members = g.map((i) => files[i]).sort(buildCmp);
    const ids = members.concat(...members.map((f) => (b.syms.get(f) || []).filter((s) => b.nodes.get(s.id).k === 'sym').map((s) => s.id)));
    // the file that names a group, and its top nodes, are code first: a README links to everything, a test imports it
    const lead = members.slice().sort((x, y) => follows(x) - follows(y) || byDegree(x, y))[0];
    const top = ids.sort((x, y) => follows(b.nodes.get(x).f) - follows(b.nodes.get(y).f) || byDegree(x, y)).slice(0, BUILD_TOP);
    return { members, lead, name: buildName(members, lead, follows), n: members.length, top };
  });
  list.sort((x, y) => y.n - x.n || buildCmp(x.name, y.name) || buildCmp(x.members[0], y.members[0]));
  // two communities in one folder: each also says its most connected file, then a number if that is not enough
  const count = (key) => list.filter((c) => c.name === key).length;
  for (const c of list.filter((c) => count(c.name) > 1)) c.name = `${c.name} (${buildBase(c.lead)})`;
  const used = new Map();
  for (const c of list) {
    const k = (used.get(c.name) || 0) + 1;
    used.set(c.name, k);
    if (k > 1) c.name = `${c.name} ${k}`;
  }
  return list;
}

function buildChunks(nodes, edges, limit) {
  if (!nodes.length) return [];
  const size = (v) => Buffer.byteLength(JSON.stringify(v));
  const byFrom = new Map();
  for (const e of edges) buildPush(byFrom, e[0], e);
  const chunks = [];
  let cur, used;
  const fresh = () => { cur = { nodes: [], edges: [] }; chunks.push(cur); used = size(cur); };
  fresh();
  for (const node of nodes) {
    const own = byFrom.get(node.i) || [], sizes = own.map((e) => size(e) + 1), nodeSize = size(node) + 1;
    // a node goes with its edges; only a node whose edges overflow a whole chunk spills them into the next
    if (used + nodeSize + sizes.reduce((a, s) => a + s, 0) > limit && (cur.nodes.length || cur.edges.length)) fresh();
    cur.nodes.push(node);
    used += nodeSize;
    own.forEach((e, k) => {
      if (used + sizes[k] > limit) fresh();
      cur.edges.push(e);
      used += sizes[k];
    });
  }
  return chunks;
}

// files: Map of repo-relative path to text (a file with no language may map to ''); opts: { repo, by, commit?,
// root?, label?, chunkBytes?, langFor? } (langFor picks a file's language; tests hand it a made-up one)
function buildGraph(files, opts = {}) {
  const paths = [...files.keys()].sort(buildCmp);
  const b = {
    paths, has: new Set(paths), bases: new Map(), lang: new Map(), parsed: new Map(), nodes: new Map(), edges: new Map(),
    syms: new Map(), byName: new Map(), byLast: new Map(), imports: new Map(), outside: new Map(), stems: new Map(),
    last: new Map(), lines: new Map(), langFor: opts.langFor || langFor,
  };
  for (const p of paths) buildPush(b.bases, buildBase(p), p);
  buildExtract(b, files);
  buildSymbols(b);
  buildImports(b);
  buildRefs(b);
  buildMentions(b);
  // a file with no language is on the map only when something imports or mentions it
  for (const [, to] of b.edges.values()) if (!b.nodes.has(to) && b.has.has(to)) b.nodes.set(to, { i: to, k: 'file', n: buildBase(to), f: to, l: 0 });
  const edges = [...b.edges.values()].filter(([from, to]) => b.nodes.has(from) && b.nodes.has(to))
    .sort((x, y) => buildCmp(x[0], y[0]) || buildCmp(x[1], y[1]) || buildCmp(x[2], y[2]));
  const degree = mapDegrees(edges);
  const communities = buildCommunities(b, degree);
  communities.slice(0, BUILD_COMMUNITIES).forEach((c, k) => {
    c.c = k;
    for (const f of c.members) for (const id of [f, ...(b.syms.get(f) || []).map((s) => s.id)]) b.nodes.get(id).c = k;
  });
  const nodes = [...b.nodes.values()].sort((x, y) => buildCmp(x.i, y.i));
  for (const n of nodes) if ((n.k === 'file' || n.k === 'doc') && buildIsTest(n.i)) n.q = 't';
  const god = nodes.filter((n) => n.k !== 'sec' && !buildIsTest(n.f) && degree.get(n.i))
    .sort((x, y) => degree.get(y.i) - degree.get(x.i) || buildCmp(x.i, y.i)).slice(0, BUILD_GOD).map((n) => n.i);
  const chunks = buildChunks(nodes, edges, opts.chunkBytes || BUILD_CHUNK_BYTES);
  const langs = {};
  for (const lang of [...b.lang.values()].map((l) => l.id).sort(buildCmp)) langs[lang] = (langs[lang] || 0) + 1;
  const kinds = (k) => nodes.filter((n) => n.k === k).length;
  const index = {
    repo: opts.repo,
    ...(opts.label ? { label: opts.label } : {}),
    ...(opts.commit ? { commit: opts.commit } : {}),
    builtAt: new Date().toISOString(),
    by: opts.by,
    ...(opts.root != null ? { root: opts.root } : {}),
    counts: { files: kinds('file'), symbols: kinds('sym'), edges: edges.length, docs: kinds('doc') },
    chunks: chunks.length,
    communities: communities.slice(0, BUILD_COMMUNITIES).map(({ c, name, n, top }) => ({ c, name, n, top })),
    god,
    langs,
    version: 1,
  };
  return { index, chunks };
}

// scan a checkout and build its map; the commit is the checked-out one unless opts says otherwise
async function mapRepo(root, opts = {}) {
  const paths = await listFiles(root);
  const texts = await readFiles(root, paths.filter((p) => langFor(p)));
  const files = new Map(paths.map((p) => [p, texts.get(p) || '']));
  const commit = opts.commit || await headCommit(root);
  return buildGraph(files, { ...opts, ...(commit ? { commit } : {}) });
}

// ---- uploader ----
// node codemap.mjs --site https://board.example --project P --repo owner/name [--root DIR] [--label L] [--token abt_…]
// The token comes from --token or ARTIBOARD_TOKEN. What leaves the machine: paths, names, line numbers, each symbol's
// declaration line (a constant's without its value) and the comment above it. No bodies.
async function codemapMain(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i++) if (argv[i].startsWith('--')) args[argv[i].slice(2)] = argv[i + 1] && !argv[i + 1].startsWith('--') ? argv[++i] : true;
  const need = (k) => { if (!args[k] || args[k] === true) { console.error(`--${k} is required`); process.exit(2); } return args[k]; };
  const site = need('site').replace(/\/$/, ''), project = need('project'), repo = need('repo');
  const token = args.token && args.token !== true ? args.token : process.env.ARTIBOARD_TOKEN;
  if (!token) { console.error('pass --token or set ARTIBOARD_TOKEN'); process.exit(2); }
  const root = args.root && args.root !== true ? args.root : process.cwd();
  const started = Date.now();
  const { index, chunks } = await mapRepo(root, { repo, label: args.label && args.label !== true ? args.label : undefined });
  // gzipped bytes as an octet stream: a map's JSON is large and hosts cap request bodies, and a host that parses
  // JSON bodies itself would choke on compressed JSON; the server inflates what starts with the gzip magic bytes
  const res = await fetch(`${site}/api/p/${encodeURIComponent(project)}/map`, {
    method: 'POST', headers: { 'Content-Type': 'application/octet-stream', Authorization: `Bearer ${token}` },
    body: gzipSync(JSON.stringify({ repo, index, chunks })),
  });
  const body = await res.json().catch(() => ({}));
  if (!res.ok) { console.error(`upload failed (${res.status}): ${body.message || body.error || 'unknown'}`); process.exit(1); }
  const c = index.counts || {};
  console.log(`${repo} → ${site}/p/${project}: ${c.files || 0} files, ${c.symbols || 0} symbols, ${c.edges || 0} edges in ${body.chunks} chunks (${Date.now() - started} ms)`);
  for (const com of (index.communities || []).slice(0, 8)) console.log(`  ${com.name} · ${com.n} files · ${(com.top || []).slice(0, 3).join(', ')}`);
}
if (import.meta.url === `file://${process.argv[1]}` || process.argv[1]?.endsWith('codemap.mjs')) codemapMain(process.argv.slice(2)).catch((e) => { console.error(e.message || e); process.exit(1); });
